   "answerTex": "<br>20 — went<br>21 — most famous<br>22 — knows<br>23 — began<br>24 — did not mind<br>25 — were<br>26 — its<br>27 — was designed<br>28 — had",
   "steps": [
    "Текст с ответами:<div class=\"eng-text\"><p><span class=\"eng-num\">20</span> It was a great day yesterday. My friends and I <b>went</b> to see a performance at the Bolshoi Theatre.</p><p><span class=\"eng-num\">21</span> You certainly know that the Bolshoi Theatre is the <b>most famous</b> theatre in Russia and probably in the world.</p><p><span class=\"eng-num\">22</span> But not everyone <b>knows</b> the history of the Bolshoi Theatre.</p><p><span class=\"eng-num\">23</span> According to historical documents, it <b>began</b> in March 1776 when Prince Pyotr Urusov was granted Royal permission to build a public theatre in Moscow.</p><p><span class=\"eng-num\">24</span> Catherine II, Empress of Russia, was fond of arts. She <b>did not mind</b> having a new theatre in her country.</p><p><span class=\"eng-num\">25</span> The original building of the theatre had a hall with almost 1,000 seats, a stage and an orchestra pit. Directly over the stage there <b>were</b> boxes where the most noble fans of the theatre had their seats.</p><p><span class=\"eng-num\">26</span> The theatre has changed several times during <b>its</b> history.</p><p><span class=\"eng-num\">27</span> The building we can see today opened in 1825. It <b>was designed</b> by architect Andrei Mikhailov who was also the architect of the Maly Theatre.</p><p><span class=\"eng-num\">28</span> Since that time, the building has been rebuilt and renovated several times. Now it looks beautiful from the inside and outside. If I <b>had</b> the opportunity to go there more often, I would do it every week.</p></div>"
   ],
