   "text": "<div class=\"eng-text\"><p class=\"eng-note\">Прочитайте приведённый ниже текст. Преобразуйте слова, напечатанные заглавными буквами в конце строк, обозначенных номерами 20 – 28, так, чтобы они грамматически соответствовали содержанию текста. Заполните пропуски полученными словами. Каждый пропуск соответствует отдельному заданию 20 – 28.</p><p><span class=\"eng-num\">20</span> I was happy to take part in the exchange programme and to go to college in Britain. An opportunity to spend two <span class=\"eng-gap\"></span> in London sounded fantastic. <span class=\"eng-word\">MONTH</span></p><p><span class=\"eng-num\">21</span> Our teacher told us that we <span class=\"eng-gap\"></span> in a student hostel. <span class=\"eng-word\">LIVE</span></p><p><span class=\"eng-num\">22</span> It was going to be <span class=\"eng-gap\"></span> than staying with a host family as the hostel was very close to the college. <span class=\"eng-word\">CONVENIENT</span></p><p><span class=\"eng-num\">23</span> When we arrived in London, the <span class=\"eng-gap\"></span> thing we had was a bus excursion round the British capital. <span class=\"eng-word\">ONE</span></p><p><span class=\"eng-num\">24</span> Unfortunately, when we <span class=\"eng-gap\"></span> Westminster Abbey, it started to rain hard. <span class=\"eng-word\">PASS</span></p><p><span class=\"eng-num\">25</span> We had to go down to the lower level of our double-decker and we <span class=\"eng-gap\"></span> to enjoy the wonderful sights. <span class=\"eng-word\">NOT MANAGE</span></p><p><span class=\"eng-num\">26</span> Anyway, London is very impressive. People from all over the world live there. Some of <span class=\"eng-gap\"></span> come as tourists, others choose this place to study or to work in. <span class=\"eng-word\">THEY</span></p><p><span class=\"eng-num\">27</span> It is a dynamic multicultural city, though there <span class=\"eng-gap\"></span> so many historical buildings in it. <span class=\"eng-word\">BE</span></p><p><span class=\"eng-num\">28</span> Amazingly, many of the houses <span class=\"eng-gap\"></span> centuries ago! <span class=\"eng-word\">BUILD</span></p></div>",
