   "peek": "Dad usually comes up with original ideas. Last Sunday Dad … that we should all go on a camping trip.",
   "text": "<div class=\"eng-text\"><p class=\"eng-note\">Прочитайте приведённый ниже текст. Преобразуйте слова, напечатанные заглавными буквами в конце строк, обозначенных номерами 20 – 28, так, чтобы они грамматически соответствовали содержанию текста. Заполните пропуски полученными словами. Каждый пропуск соответствует отдельному заданию 20 – 28.</p><p><span class=\"eng-num\">20</span> Dad usually comes up with original ideas. Last Sunday Dad <span class=\"eng-gap\"></span> that we should all go on a camping trip. <span class=\"eng-word\">DECIDE</span></p><p><span class=\"eng-num\">21</span> The idea came to him while he <span class=\"eng-gap\"></span> an article about camping. The article said that camping brings families together. <span class=\"eng-word\">READ</span></p><p><span class=\"eng-num\">22</span> “Not true”, I smiled. “What about television? It usually <span class=\"eng-gap\"></span> families to feel a lot more united.” <span class=\"eng-word\">HELP</span></p><p><span class=\"eng-num\">23</span> “If the weather is fine, we <span class=\"eng-gap\"></span> on a trip next weekend,” Dad said and put his magazine on the coffee table. <span class=\"eng-word\">GO</span></p><p><span class=\"eng-num\">24</span> I quickly looked over at my <span class=\"eng-gap\"></span> brother, Paul. <span class=\"eng-word\">YOUNG</span></p><p><span class=\"eng-num\">25</span> He gave me a knowing smile, “Do you remember <span class=\"eng-gap\"></span> last trip?” <span class=\"eng-word\">WE</span></p><p><span class=\"eng-num\">26</span> I certainly did. Last summer Dad told us that fishing would be a great family activity. We <span class=\"eng-gap\"></span> four expensive fishing rods and drove for three long hours to a big lake in Virginia. When we got there, we discovered that we had forgotten to take the fishing rods. <span class=\"eng-word\">BUY</span></p><p><span class=\"eng-num\">27</span> Ten minutes later we made another unpleasant discovery: we <span class=\"eng-gap\"></span> the tent which meant we couldn’t stay overnight and we had to drive all the way back home again. <span class=\"eng-word\">NOT HAVE</span></p><p><span class=\"eng-num\">28</span> We <span class=\"eng-gap\"></span> tired and disappointed with the trip. <span class=\"eng-word\">BE</span></p></div>",
