   "fipi": "391D3D, CB9E1B, D51A4B, BAF842, 0BC2C2, EA9FC8, E407D9, CAF14D, 7ABCBE",
   "peek": "A few years ago I was on a camping holiday in Bristol. There … lots of other girls from around the UK, but I was the only one from Scotland.",
   "text": "<div class=\"eng-text\"><p class=\"eng-note\">Прочитайте приведённый ниже текст. Преобразуйте слова, напечатанные заглавными буквами в конце строк, обозначенных номерами 20 – 28, так, чтобы они грамматически соответствовали содержанию текста. Заполните пропуски полученными словами. Каждый пропуск соответствует отдельному заданию 20 – 28.</p><p><span class=\"eng-num\">20</span> A few years ago I was on a camping holiday in Bristol. There <span class=\"eng-gap\"></span> lots of other girls from around the UK, but I was the only one from Scotland. <span class=\"eng-word\">BE</span></p><p><span class=\"eng-num\">21</span> The camp <span class=\"eng-gap\"></span> in the woods, not far from the river. <span class=\"eng-word\">LOCATE</span></p><p><span class=\"eng-num\">22</span> The camp life was even <span class=\"eng-gap\"></span> than I had expected. We enjoyed all kinds of camping activities – sports and games, different shows and contests. <span class=\"eng-word\">INTERESTING</span></p><p><span class=\"eng-num\">23</span> Everything was fine apart from one incident that took me aback. Once, at lunchtime, when I <span class=\"eng-gap\"></span> ice cream, one of the girls asked: “So, do you have ice cream in Scotland?” <span class=\"eng-word\">EAT</span></p><p><span class=\"eng-num\">24</span> I <span class=\"eng-gap\"></span> how to react. My neighbour repeated her question. I nodded, “Yes.” <span class=\"eng-word\">NOT KNOW</span></p><p><span class=\"eng-num\">25</span> My answer provoked a wave of absurd questions about my country: “Have you ever seen a ghost in your castle?” “Do all Scottish <span class=\"eng-gap\"></span> wear checked skirts?” <span class=\"eng-word\">MAN</span></p><p><span class=\"eng-num\">26</span> I <span class=\"eng-gap\"></span> out that some people believe silly stereotypes about Scotland. <span class=\"eng-word\">FIND</span></p><p><span class=\"eng-num\">27</span> They believe that Scots really carry bagpipes in <span class=\"eng-gap\"></span> bags to play the instrument on the streets, and that Scots practise magic. <span class=\"eng-word\">THEY</span></p><p><span class=\"eng-num\">28</span> At last, the girls said that they <span class=\"eng-gap\"></span> to Scotland one day to see it with their own eyes and to separate the truth from the myths. <span class=\"eng-word\">COME</span></p></div>",
