   "answerTex": "<br>20 — were<br>21 — was located<br>22 — more interesting<br>23 — was eating<br>24 — did not know<br>25 — men<br>26 — found<br>27 — their<br>28 — would come",
   "steps": [
    "Текст с ответами:<div class=\"eng-text\"><p><span class=\"eng-num\">20</span> A few years ago I was on a camping holiday in Bristol. There <b>were</b> lots of other girls from around the UK, but I was the only one from Scotland.</p><p><span class=\"eng-num\">21</span> The camp <b>was located</b> in the woods, not far from the river.</p><p><span class=\"eng-num\">22</span> The camp life was even <b>more interesting</b> than I had expected. We enjoyed all kinds of camping activities – sports and games, different shows and contests.</p><p><span class=\"eng-num\">23</span> Everything was fine apart from one incident that took me aback. Once, at lunchtime, when I <b>was eating</b> ice cream, one of the girls asked: “So, do you have ice cream in Scotland?”</p><p><span class=\"eng-num\">24</span> I <b>did not know</b> how to react. My neighbour repeated her question. I nodded, “Yes.”</p><p><span class=\"eng-num\">25</span> My answer provoked a wave of absurd questions about my country: “Have you ever seen a ghost in your castle?” “Do all Scottish <b>men</b> wear checked skirts?”</p><p><span class=\"eng-num\">26</span> I <b>found</b> out that some people believe silly stereotypes about Scotland.</p><p><span class=\"eng-num\">27</span> They believe that Scots really carry bagpipes in <b>their</b> bags to play the instrument on the streets, and that Scots practise magic.</p><p><span class=\"eng-num\">28</span> At last, the girls said that they <b>would come</b> to Scotland one day to see it with their own eyes and to separate the truth from the myths.</p></div>"
   ],
