   "text": "<div class=\"eng-text\"><p class=\"eng-note\">Прочитайте приведённый ниже текст. Преобразуйте слова, напечатанные заглавными буквами в конце строк, обозначенных номерами 20 – 28, так, чтобы они грамматически соответствовали содержанию текста. Заполните пропуски полученными словами. Каждый пропуск соответствует отдельному заданию 20 – 28.</p><p><span class=\"eng-num\">20</span> Anna was glad that the academic year was about to finish. Like most <span class=\"eng-gap\"></span> she was looking forward to the summer but not because she wanted to relax. <span class=\"eng-word\">CHILD</span></p><p><span class=\"eng-num\">21</span> Her plans <span class=\"eng-gap\"></span> ambitious. Anna wanted to buy a professional digital camera and it wasn’t easy to save enough money. <span class=\"eng-word\">BE</span></p><p><span class=\"eng-num\">22</span> Anna had already chosen the model she wanted. Her dad said that he <span class=\"eng-gap\"></span> her the camera in a couple of years. <span class=\"eng-word\">GIVE</span></p><p><span class=\"eng-num\">23</span> But Anna <span class=\"eng-gap\"></span> wait so long, she needed it right then. <span class=\"eng-word\">NOT CAN</span></p><p><span class=\"eng-num\">24</span> “If I <span class=\"eng-gap\"></span> it now, I would be able to take part in the Professional Photograph Competition. <span class=\"eng-word\">HAVE</span></p><p><span class=\"eng-num\">25</span> Everyone says I’ve got talent,” she said to herself, looking at the magazine where an article about the competition <span class=\"eng-gap\"></span>. <span class=\"eng-word\">PUBLISH</span></p><p><span class=\"eng-num\">26</span> While she was reading the article for the <span class=\"eng-gap\"></span> time, a brilliant idea came to her – why not take up a summer job as a photographer? <span class=\"eng-word\">TWO</span></p><p><span class=\"eng-num\">27</span> She reached for the phone and dialed the number of the <span class=\"eng-gap\"></span> photography agency in the town. <span class=\"eng-word\">LARGE</span></p><p><span class=\"eng-num\">28</span> “Hello, can I help you?” the woman’s voice sounded encouraging and Anna <span class=\"eng-gap\"></span> that she probably had a chance. <span class=\"eng-word\">THINK</span></p></div>",
