   "text": "<div class=\"eng-text\"><p class=\"eng-note\">Прочитайте приведённый ниже текст. Преобразуйте слова, напечатанные заглавными буквами в конце строк, обозначенных номерами 20 – 28, так, чтобы они грамматически соответствовали содержанию текста. Заполните пропуски полученными словами. Каждый пропуск соответствует отдельному заданию 20 – 28.</p><p><span class=\"eng-num\">20</span> Mike Fay is a famous biologist. He is well-known for his 2,000-mile walk across Africa. It <span class=\"eng-gap\"></span> him 455 days. <span class=\"eng-word\">TAKE</span></p><p><span class=\"eng-num\">21</span> His expedition started in 2001. It <span class=\"eng-gap\"></span> to draw attention to the African forests. During his expedition Mike Fay made several films about the beauty of the forests. <span class=\"eng-word\">ORGANIZE</span></p><p><span class=\"eng-num\">22</span> He said they were the<span class=\"eng-gap\"></span> natural sights he had ever seen. <span class=\"eng-word\">WONDERFUL</span></p><p><span class=\"eng-num\">23</span> His films<span class=\"eng-gap\"></span> a success. Thanks to them the governments of several African countries agreed to create 13 national parks. <span class=\"eng-word\">BE</span></p><p><span class=\"eng-num\">24</span> Mike commented that 26,000 square kilometres of the forest were saved for the future and for our <span class=\"eng-gap\"></span>. <span class=\"eng-word\">CHILD</span></p><p><span class=\"eng-num\">25</span> At the moment Mike works for the National Geographic. Recently he <span class=\"eng-gap\"></span> several projects for the magazine. His job involves lots of travelling, which is sometimes not very safe. <span class=\"eng-word\">COMPLETE</span></p><p><span class=\"eng-num\">26</span> Not long ago, Mike came face to face with an elephant which attacked<span class=\"eng-gap\"></span>. Mike was injured but luckily not seriously. <span class=\"eng-word\">HE</span></p><p><span class=\"eng-num\">27</span> But danger could never stop Mike. “I wish everyone <span class=\"eng-gap\"></span> that life is a very delicate thing. <span class=\"eng-word\">UNDERSTAND</span></p><p><span class=\"eng-num\">28</span> If we go on in the same irresponsible way, we <span class=\"eng-gap\"></span> all life on the planet, and ourselves too”. <span class=\"eng-word\">KILL</span></p></div>",
