   "text": "<div class=\"eng-text\"><p class=\"eng-note\">Прочитайте приведённый ниже текст. Преобразуйте слова, напечатанные заглавными буквами в конце строк, обозначенных номерами 20 – 28, так, чтобы они грамматически соответствовали содержанию текста. Заполните пропуски полученными словами. Каждый пропуск соответствует отдельному заданию 20 – 28.</p><p><span class=\"eng-num\">20</span> It started as a normal Monday morning. My alarm clock woke <span class=\"eng-gap\"></span> up early in the morning. <span class=\"eng-word\">I</span></p><p><span class=\"eng-num\">21</span> I had breakfast, brushed my teeth and <span class=\"eng-gap\"></span> outside to catch the bus. <span class=\"eng-word\">RUN</span></p><p><span class=\"eng-num\">22</span> At school I noticed that something was different. I came up to my friend Laura and asked her: “What’s going on? Why <span class=\"eng-gap\"></span> everyone so excited?” <span class=\"eng-word\">BE</span></p><p><span class=\"eng-num\">23</span> “Don’t you know?” she said. “All the teachers <span class=\"eng-gap\"></span> for a conference. Only the headteacher and a few of the school staff are here. <span class=\"eng-word\">LEAVE</span></p><p><span class=\"eng-num\">24</span> The senior students will be teaching us today. They are only two or three years <span class=\"eng-gap\"></span> than us. How can they possibly teach us?” <span class=\"eng-word\">OLD</span></p><p><span class=\"eng-num\">25</span> However, she was wrong. Our substitute teacher, a student two grades above, was very serious. He said that he <span class=\"eng-gap\"></span> some French poetry to us. <span class=\"eng-word\">EXPLAIN</span></p><p><span class=\"eng-num\">26</span> It was an unusual, but interesting French class. The poem <span class=\"eng-gap\"></span> on the board, our new teacher read it and then we discussed the poet’s message, choice of words and other poetical things. <span class=\"eng-word\">WRITE</span></p><p><span class=\"eng-num\">27</span> Probably because the teacher was almost the same age as us, we felt relaxed and spoke freely. He also told us several amusing <span class=\"eng-gap\"></span> about the poet and his time. When the class was almost over, our substitute teacher invited us to attend the next session of the school literary society. <span class=\"eng-word\">STORY</span></p><p><span class=\"eng-num\">28</span> “I’m the Chairman of the society,” he added, “If you come, we <span class=\"eng-gap\"></span> a special welcome party for new members.” <span class=\"eng-word\">HAVE</span></p></div>",
