   "text": "<div class=\"eng-text\"><p class=\"eng-note\">Прочитайте приведённый ниже текст. Преобразуйте слова, напечатанные заглавными буквами в конце строк, обозначенных номерами 20 – 28, так, чтобы они грамматически соответствовали содержанию текста. Заполните пропуски полученными словами. Каждый пропуск соответствует отдельному заданию 20 – 28.</p><p><span class=\"eng-num\">20</span> It was the middle of November and Tina felt down and depressed. Late autumn was the <span class=\"eng-gap\"></span> season of the year. <span class=\"eng-word\">BAD</span></p><p><span class=\"eng-num\">21</span> It often <span class=\"eng-gap\"></span>, and Tina had to spend most of her time indoors. Because of this, she really welcomed the changes in her school routine. The school administration introduced a new class - a dance class. <span class=\"eng-word\">RAIN</span></p><p><span class=\"eng-num\">22</span> But not everyone was happy! The boys said that it <span class=\"eng-gap\"></span> a waste of time. <span class=\"eng-word\">BE</span></p><p><span class=\"eng-num\">23</span> They often missed the class and, when they attended, they <span class=\"eng-gap\"></span> to the teacher’s instructions but tried to make fun of everything. <span class=\"eng-word\">NOT LISTEN</span></p><p><span class=\"eng-num\">24</span> “I wish we <span class=\"eng-gap\"></span> a class for girls only,” Tina thought. <span class=\"eng-word\">HAVE</span></p><p><span class=\"eng-num\">25</span> The Junior Dance Competition <span class=\"eng-gap\"></span> in their town every year. It was a spectacular show. <span class=\"eng-word\">HOLD</span></p><p><span class=\"eng-num\">26</span> “Your dancing <span class=\"eng-gap\"></span> every day,” the teacher said one day. <span class=\"eng-word\">IMPROVE</span></p><p><span class=\"eng-num\">27</span> “If you go on like this, you <span class=\"eng-gap\"></span> a chance to take part in the Dance Competition next month.” <span class=\"eng-word\">HAVE</span></p><p><span class=\"eng-num\">28</span> Tina imagined herself wearing a beautiful dress and elegant shoes on her <span class=\"eng-gap\"></span>. She decided it was something she’d like to try. <span class=\"eng-word\">FOOT</span></p></div>",
