   "peek": "It was a nice sunny day and mum decided to take us to the zoo. My younger sister, Wendy, was delighted. She enjoyed books and films about animals but she had never been to the zoo. “How many animals live in the zoo? Can we give … some food?",
   "text": "<div class=\"eng-text\"><p class=\"eng-note\">Прочитайте приведённый ниже текст. Преобразуйте слова, напечатанные заглавными буквами в конце строк, обозначенных номерами 20 – 28, так, чтобы они грамматически соответствовали содержанию текста. Заполните пропуски полученными словами. Каждый пропуск соответствует отдельному заданию 20 – 28.</p><p><span class=\"eng-num\">20</span> It was a nice sunny day and mum decided to take us to the zoo. My younger sister, Wendy, was delighted. She enjoyed books and films about animals but she had never been to the zoo. “How many animals live in the zoo? Can we give <span class=\"eng-gap\"></span> some food? <span class=\"eng-word\">THEY</span></p><p><span class=\"eng-num\">21</span> Are there any crocodiles? Who <span class=\"eng-gap\"></span> care of the lions?” My sister was very excited and asked a lot of questions. <span class=\"eng-word\">TAKE</span></p><p><span class=\"eng-num\">22</span> She kept talking all the time and <span class=\"eng-gap\"></span> that nobody was answering her questions. <span class=\"eng-word\">NOT MIND</span></p><p><span class=\"eng-num\">23</span> When we <span class=\"eng-gap\"></span> at the zoo, it was midday. <span class=\"eng-word\">ARRIVE</span></p><p><span class=\"eng-num\">24</span> There <span class=\"eng-gap\"></span> a lot of people everywhere. <span class=\"eng-word\">BE</span></p><p><span class=\"eng-num\">25</span> The territory of the zoo was large, and the animals <span class=\"eng-gap\"></span> in large enclosures that imitated their natural environment. <span class=\"eng-word\">KEEP</span></p><p><span class=\"eng-num\">26</span> When we went up to the enclosure that had a family of Indian elephants, they <span class=\"eng-gap\"></span> their lunch. They were focused on their food and didn’t pay much attention to the visitors. <span class=\"eng-word\">HAVE</span></p><p><span class=\"eng-num\">27</span> “They are the <span class=\"eng-gap\"></span> animals I’ve ever seen,” said Wendy in an impressed voice. <span class=\"eng-word\">LARGE</span></p><p><span class=\"eng-num\">28</span> “I wish we <span class=\"eng-gap\"></span> keep a baby elephant as a pet.” Mum said nothing and we proceeded to the pool that had the seals and penguins. <span class=\"eng-word\">CAN</span></p></div>",
