   "text": "<div class=\"eng-text\"><p class=\"eng-note\">Прочитайте приведённый ниже текст. Преобразуйте слова, напечатанные заглавными буквами в конце строк, обозначенных номерами 20 – 28, так, чтобы они грамматически соответствовали содержанию текста. Заполните пропуски полученными словами. Каждый пропуск соответствует отдельному заданию 20 – 28.</p><p><span class=\"eng-num\">20</span> A few days ago Kim’s family moved house. Kim had very mixed feelings about it. On the one hand, she <span class=\"eng-gap\"></span> happy with her new room. <span class=\"eng-word\">FEEL</span></p><p><span class=\"eng-num\">21</span> It was larger than the room she used to live in. Everything in this room <span class=\"eng-gap\"></span> in Kim’s favourite colours and according to her taste. <span class=\"eng-word\">ARRANGE</span></p><p><span class=\"eng-num\">22</span> The flat was on the <span class=\"eng-gap\"></span> floor in an old brick building. <span class=\"eng-word\">FIVE</span></p><p><span class=\"eng-num\">23</span> From her window Kim could see the large garden, which now was covered with bright yellow <span class=\"eng-gap\"></span>, and the tiled roofs at a distance. <span class=\"eng-word\">LEAF</span></p><p><span class=\"eng-num\">24</span> “I’d be very happy if I <span class=\"eng-gap\"></span> here,” Kim’s friend, Jessica, said when she visited her for the first time. <span class=\"eng-word\">LIVE</span></p><p><span class=\"eng-num\">25</span> “And how is your new school?” she asked, still admiring the fresh wallpapered walls with a few framed photos on <span class=\"eng-gap\"></span>. <span class=\"eng-word\">THEY</span></p><p><span class=\"eng-num\">26</span> “You <span class=\"eng-gap\"></span> new friends there, right?” These words made Kim feel nervous. “No, not yet,” she answered. <span class=\"eng-word\">MAKE</span></p><p><span class=\"eng-num\">27</span> Then she said that she <span class=\"eng-gap\"></span> to her new school only the next Monday and that the school looked nice and modern and there was a swimming pool in it. <span class=\"eng-word\">GO</span></p><p><span class=\"eng-num\">28</span> What Kim <span class=\"eng-gap\"></span> her friend was that she was awfully afraid of going there and meeting her new classmates and teachers. <span class=\"eng-word\">NOT TELL</span></p></div>",
