    "Текст с ответами:<div class=\"eng-text\"><p><span class=\"eng-num\">20</span> Jeff woke up late. The house was very quiet and Jeff <b>understood</b> that he was alone there. He got up and headed to the kitchen.</p><p><span class=\"eng-num\">21</span> There <b>was</b> nobody in it but he felt the delicious aroma of fresh baking.</p><p><span class=\"eng-num\">22</span> A large bowl of doughnuts was on the table. It <b>was covered</b> with a white kitchen towel but Jeff could not resist it and pulled out a doughnut.</p><p><span class=\"eng-num\">23</span> When he was consuming his <b>fifth</b> one, his grandmother appeared at the doorway.</p><p><span class=\"eng-num\">24</span> She <b>was wearing</b> light working trousers, a T-shirt, and an old straw hat.</p><p><span class=\"eng-num\">25</span> Jeff guessed that she had been working on <b>her</b> roses, in the front garden.</p><p><span class=\"eng-num\">26</span> “Fine, you <b>have woken</b> up at last!” said Granny, “But why are you still undressed? Go and wash and get dressed immediately!”</p><p><span class=\"eng-num\">27</span> Jeff remembered that Granny had always been very strict about the morning routine. She never allowed her grandchildren to look untidy or avoid brushing their <b>teeth</b>.</p><p><span class=\"eng-num\">28</span> “Ok-ok, just a second,” laughed Jeff picking up another doughnut and retreating through the other door. “I <b>will come</b> as soon as I am ready.”</p></div>"
