   "text": "<div class=\"eng-text\"><p class=\"eng-note\">Прочитайте приведённый ниже текст. Преобразуйте слова, напечатанные заглавными буквами в конце строк, обозначенных номерами 20 – 28, так, чтобы они грамматически соответствовали содержанию текста. Заполните пропуски полученными словами. Каждый пропуск соответствует отдельному заданию 20 – 28.</p><p><span class=\"eng-num\">20</span> Susan’s father often had to go to different countries on business. That evening, he came home <span class=\"eng-gap\"></span> than usual. <span class=\"eng-word\">LATE</span></p><p><span class=\"eng-num\">21</span> He looked tired. Susan <span class=\"eng-gap\"></span> that the next week her father was going to China to discuss a new project. <span class=\"eng-word\">KNOW</span></p><p><span class=\"eng-num\">22</span> At dinner, her father asked Susan if she <span class=\"eng-gap\"></span> to go with him. It was a bit unexpected but Susan liked the idea at once. <span class=\"eng-word\">WANT</span></p><p><span class=\"eng-num\">23</span> It was her <span class=\"eng-gap\"></span> birthday in a few days. <span class=\"eng-word\">SIXTEEN</span></p><p><span class=\"eng-num\">24</span> And Susan thought it <span class=\"eng-gap\"></span> fun to celebrate it abroad. <span class=\"eng-word\">BE</span></p><p><span class=\"eng-num\">25</span> However, there was one thing she wanted to clear up before the trip: “Are you going to be busy from morning till night? I <span class=\"eng-gap\"></span> to sit in the hotel all the time alone.” <span class=\"eng-word\">NOT WANT</span></p><p><span class=\"eng-num\">26</span> “You won’t have to,” her father reassured Susan. “I <span class=\"eng-gap\"></span> all the project papers already. So, while our partners are studying them, we’ll have plenty of time for sightseeing.” <span class=\"eng-word\">PREPARE</span></p><p><span class=\"eng-num\">27</span> “Great!” Susan ran up to her room to pack. “Remember to take some comfortable shoes. Otherwise your <span class=\"eng-gap\"></span> will hurt after the long excursions.” Her father’s advice was always practical. <span class=\"eng-word\">FOOT</span></p><p><span class=\"eng-num\">28</span> In half an hour everything <span class=\"eng-gap\"></span> in a suitcase and Susan called her best friend to tell her the news. <span class=\"eng-word\">PACK</span></p></div>",
