   "text": "<div class=\"eng-text\"><p class=\"eng-note\">Прочитайте приведённый ниже текст. Преобразуйте слова, напечатанные заглавными буквами в конце строк, обозначенных номерами 20 – 28, так, чтобы они грамматически соответствовали содержанию текста. Заполните пропуски полученными словами. Каждый пропуск соответствует отдельному заданию 20 – 28.</p><p><span class=\"eng-num\">20</span> Tim liked going to the zoo. One day his mother said: “We’re going to a different place today, Tim. It’s an animal shelter. I’m sure you <span class=\"eng-gap\"></span> it.” <span class=\"eng-word\">LIKE</span></p><p><span class=\"eng-num\">21</span> The place was much <span class=\"eng-gap\"></span> than a zoo, but clean and well kept. There were volunteers in special uniforms. One of them showed Tim and his mum round the shelter. <span class=\"eng-word\">SMALL</span></p><p><span class=\"eng-num\">22</span> Lots of animals <span class=\"eng-gap\"></span> there. <span class=\"eng-word\">KEEP</span></p><p><span class=\"eng-num\">23</span> Cats and dogs made up most of the population, but there were also horses, monkeys, <span class=\"eng-gap\"></span> and other animals. <span class=\"eng-word\">FOX</span></p><p><span class=\"eng-num\">24</span> Each of the animals had its own story written on a sign next to its cage or enclosure. All the stories were sad – the animals had either been abandoned by <span class=\"eng-gap\"></span> owners or saved by the animal police from cruel treatment. <span class=\"eng-word\">THEY</span></p><p><span class=\"eng-num\">25</span> “If people <span class=\"eng-gap\"></span> more responsible for their pets, we wouldn’t have so much work here,” the volunteer remarked. <span class=\"eng-word\">BE</span></p><p><span class=\"eng-num\">26</span> “But unfortunately some people <span class=\"eng-gap\"></span> that animals are not toys.” <span class=\"eng-word\">NOT UNDERSTAND</span></p><p><span class=\"eng-num\">27</span> Tim’s mother thanked the volunteer and <span class=\"eng-gap\"></span> a donation. Shelters always needed money to pay for the animals’ food and medical care. <span class=\"eng-word\">MAKE</span></p><p><span class=\"eng-num\">28</span> On the way home Tim told his mother that he <span class=\"eng-gap\"></span> to go to the shelter again, not only to watch but also to help the volunteers. <span class=\"eng-word\">WANT</span></p></div>",
