   "text": "<div class=\"eng-text\"><p class=\"eng-note\">Прочитайте приведённый ниже текст. Преобразуйте слова, напечатанные заглавными буквами в конце строк, обозначенных номерами 20 – 28, так, чтобы они грамматически соответствовали содержанию текста. Заполните пропуски полученными словами. Каждый пропуск соответствует отдельному заданию 20 – 28.</p><p><span class=\"eng-num\">20</span> It was about 6pm when I heard a knock on the door. It <span class=\"eng-gap\"></span> Jason, my teenage neighbour. He looked cold and upset. <span class=\"eng-word\">BE</span></p><p><span class=\"eng-num\">21</span> “What’s wrong, Jason?” “I <span class=\"eng-gap\"></span> my key and I can’t get into my house.” <span class=\"eng-word\">LOSE</span></p><p><span class=\"eng-num\">22</span> “Come in. Today’s not a day for long walks, or long waits,” I looked out the window. It <span class=\"eng-gap\"></span> hard and it was windy. <span class=\"eng-word\">SNOW</span></p><p><span class=\"eng-num\">23</span> The weather was getting <span class=\"eng-gap\"></span> every hour. <span class=\"eng-word\">BAD</span></p><p><span class=\"eng-num\">24</span> Jason <span class=\"eng-gap\"></span> off his coat and boots. <span class=\"eng-word\">TAKE</span></p><p><span class=\"eng-num\">25</span> His <span class=\"eng-gap\"></span> were wet and I gave him a pair of socks to change into. A cup of hot tea and some biscuits soon made the boy feel warm. <span class=\"eng-word\">FOOT</span></p><p><span class=\"eng-num\">26</span> “Where are your parents, Jason?” “I <span class=\"eng-gap\"></span>. <span class=\"eng-word\">NOT KNOW</span></p><p><span class=\"eng-num\">27</span> I can’t call them because of this,” he pulled his phone out of his pocket and showed it to me – the screen <span class=\"eng-gap\"></span> and the phone was obviously dead. <span class=\"eng-word\">BREAK</span></p><p><span class=\"eng-num\">28</span> Jason focused on the food again. He took his <span class=\"eng-gap\"></span> biscuit and said, “I wish my mum could make biscuits like this.” <span class=\"eng-word\">FOUR</span></p></div>",
