   "text": "<div class=\"eng-text\"><p class=\"eng-note\">Прочитайте приведённый ниже текст. Преобразуйте слова, напечатанные заглавными буквами в конце строк, обозначенных номерами 20 – 28, так, чтобы они грамматически соответствовали содержанию текста. Заполните пропуски полученными словами. Каждый пропуск соответствует отдельному заданию 20 – 28.</p><p><span class=\"eng-num\">20</span> I play the violin in the college orchestra. Last month we <span class=\"eng-gap\"></span> part in a music festival in France. <span class=\"eng-word\">TAKE</span></p><p><span class=\"eng-num\">21</span> I worried a lot before we left for France as I had never been away from home for so long. Mum tried to encourage <span class=\"eng-gap\"></span>. <span class=\"eng-word\">I</span></p><p><span class=\"eng-num\">22</span> She said that we <span class=\"eng-gap\"></span> well. <span class=\"eng-word\">PERFORM</span></p><p><span class=\"eng-num\">23</span> And she was right. We performed very successfully. It was a great journey though there <span class=\"eng-gap\"></span> some things I missed very much while being in France. <span class=\"eng-word\">BE</span></p><p><span class=\"eng-num\">24</span> One of them was my favourite mug. Without it, neither tea nor soup tasted like at home. Another thing was the warmth. The floor in my room at home <span class=\"eng-gap\"></span> with a thick carpet. <span class=\"eng-word\">COVER</span></p><p><span class=\"eng-num\">25</span> In our place in France the floor was icy cold with no carpet at all. My <span class=\"eng-gap\"></span> were always cold. <span class=\"eng-word\">FOOT</span></p><p><span class=\"eng-num\">26</span> “If it goes on like this, I <span class=\"eng-gap\"></span> a cold,” I told my roommate, Cathy. <span class=\"eng-word\">CATCH</span></p><p><span class=\"eng-num\">27</span> “I wish I <span class=\"eng-gap\"></span> a pair of woolen socks. But I left them at home.” <span class=\"eng-word\">HAVE</span></p><p><span class=\"eng-num\">28</span> “You can take mine if you want,” said Cathy. I thanked her but her socks were two sizes <span class=\"eng-gap\"></span> than I needed! <span class=\"eng-word\">SMALL</span></p></div>",
