   "text": "<div class=\"eng-text\"><p class=\"eng-note\">Прочитайте приведённый ниже текст. Преобразуйте слова, напечатанные заглавными буквами в конце строк, обозначенных номерами 20 – 28, так, чтобы они грамматически соответствовали содержанию текста. Заполните пропуски полученными словами. Каждый пропуск соответствует отдельному заданию 20 – 28.</p><p><span class=\"eng-num\">20</span> Martin was in a hurry as he had to be in the office as soon as possible. His boss <span class=\"eng-gap\"></span> it when anyone missed the morning meetings and Martin had already been late several times that week. <span class=\"eng-word\">NOT LIKE</span></p><p><span class=\"eng-num\">21</span> His boss had warned him: “If you are late again, you <span class=\"eng-gap\"></span> your job.” <span class=\"eng-word\">LOSE</span></p><p><span class=\"eng-num\">22</span> Martin was afraid of losing his job. His colleagues were nice to him, the salary was good and he sometimes <span class=\"eng-gap\"></span> on business trips abroad. <span class=\"eng-word\">GO</span></p><p><span class=\"eng-num\">23</span> It was actually the <span class=\"eng-gap\"></span> job he had ever had. <span class=\"eng-word\">GOOD</span></p><p><span class=\"eng-num\">24</span> He ran out of the house, jumped into his car and backed up without looking. BOOM! There <span class=\"eng-gap\"></span> a sound like someone hitting a drum. Martin had hit the car behind him. <span class=\"eng-word\">BE</span></p><p><span class=\"eng-num\">25</span> “Oh, no!” Martin exclaimed. Martin glanced at his watch. It was 7:18. He looked around. There were no <span class=\"eng-gap\"></span> on the street and he decided to drive off quickly. <span class=\"eng-word\">POLICEMAN</span></p><p><span class=\"eng-num\">26</span> It took <span class=\"eng-gap\"></span> 20 minutes to get to work. <span class=\"eng-word\">HE</span></p><p><span class=\"eng-num\">27</span> The boss was not around. “Thank goodness,” Martin said to himself and sat down at his desk to work. The boss arrived an hour later. “Somebody hit my car and left without leaving a note,” he said angrily. “I wish I <span class=\"eng-gap\"></span> who he was. <span class=\"eng-word\">KNOW</span></p><p><span class=\"eng-num\">28</span> My car was absolutely new! It <span class=\"eng-gap\"></span> only a week ago.” Martin went up to the window, saw the car and understood that he would lose his job anyway. <span class=\"eng-word\">BUY</span></p></div>",
