   "text": "<div class=\"eng-text\"><p class=\"eng-note\">Прочитайте приведённый ниже текст. Преобразуйте слова, напечатанные заглавными буквами в конце строк, обозначенных номерами 20 – 28, так, чтобы они грамматически соответствовали содержанию текста. Заполните пропуски полученными словами. Каждый пропуск соответствует отдельному заданию 20 – 28.</p><p><span class=\"eng-num\">20</span> English, Welsh, Scottish…all these languages sound familiar. But I’m sure you <span class=\"eng-gap\"></span> of Cornish. <span class=\"eng-word\">NOT HEAR</span></p><p><span class=\"eng-num\">21</span> I wish I <span class=\"eng-gap\"></span> it, like my Granny does. <span class=\"eng-word\">KNOW</span></p><p><span class=\"eng-num\">22</span> Cornish is a Celtic language, used in Cornwall, a county in south-west England. <span class=\"eng-gap\"></span> ago, when the Anglo-Saxons invaded Britain, many Celts moved to the mountain areas. <span class=\"eng-word\">CENTURY</span></p><p><span class=\"eng-num\">23</span> Some Celts even <span class=\"eng-gap\"></span> the country completely and settled in France. <span class=\"eng-word\">LEAVE</span></p><p><span class=\"eng-num\">24</span> Speakers of Cornish stayed in the south-west. There the language <span class=\"eng-gap\"></span> until the late 1700s. But the number of speakers got smaller and the language almost disappeared. <span class=\"eng-word\">SPEAK</span></p><p><span class=\"eng-num\">25</span> At the beginning of the <span class=\"eng-gap\"></span> century, academics became interested in Cornish and started to study the ancient texts. From those old documents they managed to restore the language! <span class=\"eng-word\">TWENTY</span></p><p><span class=\"eng-num\">26</span> Nowadays, if you visit Cornwall, you will hear a lot of it. The language <span class=\"eng-gap\"></span> as an option in many universities, and students themselves choose to learn it. <span class=\"eng-word\">OFFER</span></p><p><span class=\"eng-num\">27</span> Like I did. I think it’s the <span class=\"eng-gap\"></span> language I have ever learnt, but it’s interesting and it sounds very nice. <span class=\"eng-word\">DIFFICULT</span></p><p><span class=\"eng-num\">28</span> I believe the Cornish language <span class=\"eng-gap\"></span>. <span class=\"eng-word\">SURVIVE</span></p></div>",
