   "text": "<div class=\"eng-text\"><p class=\"eng-note\">Прочитайте приведённый ниже текст. Преобразуйте слова, напечатанные заглавными буквами в конце строк, обозначенных номерами 20 – 28, так, чтобы они грамматически соответствовали содержанию текста. Заполните пропуски полученными словами. Каждый пропуск соответствует отдельному заданию 20 – 28.</p><p><span class=\"eng-num\">20</span> Jane liked going to the park with her mum. One day when they were there, she said, “There is so much rubbish on the ground.” They looked around. There were old <span class=\"eng-gap\"></span>, waste paper and cans on the ground. <span class=\"eng-word\">BOX</span></p><p><span class=\"eng-num\">21</span> Several benches <span class=\"eng-gap\"></span>. <span class=\"eng-word\">BREAK</span></p><p><span class=\"eng-num\">22</span> “You are right,” her mum said. “I wish people <span class=\"eng-gap\"></span> about the environment more.” <span class=\"eng-word\">CARE</span></p><p><span class=\"eng-num\">23</span> “I do care about it but I <span class=\"eng-gap\"></span> what I can do to help the park,” said Jane. <span class=\"eng-word\">NOT KNOW</span></p><p><span class=\"eng-num\">24</span> Jane and her mum went home. In the evening she painted a picture of the park. At the top of the picture she <span class=\"eng-gap\"></span> “PLEASE KEEP ME CLEAN”. <span class=\"eng-word\">WRITE</span></p><p><span class=\"eng-num\">25</span> The next day Jane and her mum went to the park <span class=\"eng-gap\"></span> than usual. Jane taped her picture onto a big rubbish bin and started picking up rubbish. <span class=\"eng-word\">EARLY</span></p><p><span class=\"eng-num\">26</span> Some children ran over to see what was going on. They decided to help Jane. Soon all the rubbish was in the bags. “Good job,” Jane said, “We <span class=\"eng-gap\"></span> half of the park. <span class=\"eng-word\">CLEAN</span></p><p><span class=\"eng-num\">27</span> If we come and complete the other part tomorrow, the whole park <span class=\"eng-gap\"></span> clean and tidy. <span class=\"eng-word\">BE</span></p><p><span class=\"eng-num\">28</span> I hope people won’t throw <span class=\"eng-gap\"></span> rubbish here any more.” <span class=\"eng-word\">THEY</span></p></div>",
