   "text": "<div class=\"eng-text\"><p class=\"eng-note\">Прочитайте приведённый ниже текст. Преобразуйте слова, напечатанные заглавными буквами в конце строк, обозначенных номерами 20 – 28, так, чтобы они грамматически соответствовали содержанию текста. Заполните пропуски полученными словами. Каждый пропуск соответствует отдельному заданию 20 – 28.</p><p><span class=\"eng-num\">20</span> Jane was not an ordinary girl. She was an extremely popular person due to <span class=\"eng-gap\"></span> unusual gift. <span class=\"eng-word\">SHE</span></p><p><span class=\"eng-num\">21</span> She was very good at arranging all sorts of <span class=\"eng-gap\"></span> and events. <span class=\"eng-word\">PARTY</span></p><p><span class=\"eng-num\">22</span> In fact, all the scripts and programmes for our school events <span class=\"eng-gap\"></span> by Jane. We helped her as much as we could but she always did most of the work. <span class=\"eng-word\">WRITE</span></p><p><span class=\"eng-num\">23</span> Once I asked Jane if she could help me to make a surprise for my mum. Jane <span class=\"eng-gap\"></span> at once. <span class=\"eng-word\">AGREE</span></p><p><span class=\"eng-num\">24</span> “I <span class=\"eng-gap\"></span> you, no problem,” she said, “But I need to know some details about your mum.” <span class=\"eng-word\">HELP</span></p><p><span class=\"eng-num\">25</span> Jane asked me about what time my mum usually got up and when she went to bed, what food she liked and hated, what her favourite films, colours, and flowers <span class=\"eng-gap\"></span>. <span class=\"eng-word\">BE</span></p><p><span class=\"eng-num\">26</span> She asked me a lot of questions and I <span class=\"eng-gap\"></span> answer most of them. <span class=\"eng-word\">NOT CAN</span></p><p><span class=\"eng-num\">27</span> I felt uneasy but Jane laughed, “It’s a common thing. Unfortunately, we often do not notice even our own family – our parents, sisters and brothers. If we <span class=\"eng-gap\"></span> other people better, we would understand them better. <span class=\"eng-word\">KNOW</span></p><p><span class=\"eng-num\">28</span> And we would be much <span class=\"eng-gap\"></span> to them, wouldn’t we?” <span class=\"eng-word\">KIND</span></p></div>",
