   "answerTex": "<br>20 — her<br>21 — parties<br>22 — were written<br>23 — agreed<br>24 — will help<br>25 — were<br>26 — could not<br>27 — knew<br>28 — kinder",
   "steps": [
    "Текст с ответами:<div class=\"eng-text\"><p><span class=\"eng-num\">20</span> Jane was not an ordinary girl. She was an extremely popular person due to <b>her</b> unusual gift.</p><p><span class=\"eng-num\">21</span> She was very good at arranging all sorts of <b>parties</b> and events.</p><p><span class=\"eng-num\">22</span> In fact, all the scripts and programmes for our school events <b>were written</b> by Jane. We helped her as much as we could but she always did most of the work.</p><p><span class=\"eng-num\">23</span> Once I asked Jane if she could help me to make a surprise for my mum. Jane <b>agreed</b> at once.</p><p><span class=\"eng-num\">24</span> “I <b>will help</b> you, no problem,” she said, “But I need to know some details about your mum.”</p><p><span class=\"eng-num\">25</span> Jane asked me about what time my mum usually got up and when she went to bed, what food she liked and hated, what her favourite films, colours, and flowers <b>were</b>.</p><p><span class=\"eng-num\">26</span> She asked me a lot of questions and I <b>could not</b> answer most of them.</p><p><span class=\"eng-num\">27</span> I felt uneasy but Jane laughed, “It’s a common thing. Unfortunately, we often do not notice even our own family – our parents, sisters and brothers. If we <b>knew</b> other people better, we would understand them better.</p><p><span class=\"eng-num\">28</span> And we would be much <b>kinder</b> to them, wouldn’t we?”</p></div>"
   ],
