   "text": "<div class=\"eng-text\"><p class=\"eng-note\">Прочитайте приведённый ниже текст. Преобразуйте слова, напечатанные заглавными буквами в конце строк, обозначенных номерами 20 – 28, так, чтобы они грамматически соответствовали содержанию текста. Заполните пропуски полученными словами. Каждый пропуск соответствует отдельному заданию 20 – 28.</p><p><span class=\"eng-num\">20</span> Kathy looked at her new room’s white walls. “They’re so plain.” “Don’t worry,” Dad said, “If you don’t like them, we <span class=\"eng-gap\"></span> the walls any colour you like.” <span class=\"eng-word\">MAKE</span></p><p><span class=\"eng-num\">21</span> “Do you want pink?” Mum suggested. Kathy <span class=\"eng-gap\"></span> her head. <span class=\"eng-word\">SHAKE</span></p><p><span class=\"eng-num\">22</span> “No, pink is either for <span class=\"eng-gap\"></span> or for silly girls who like Barbie dolls. I’m neither of those.” <span class=\"eng-word\">BABY</span></p><p><span class=\"eng-num\">23</span> Her parents smiled but <span class=\"eng-gap\"></span> anything. <span class=\"eng-word\">NOT SAY</span></p><p><span class=\"eng-num\">24</span> “But what colour to choose? I wish we <span class=\"eng-gap\"></span> ask a designer for professional advice,” said Kathy. <span class=\"eng-word\">CAN</span></p><p><span class=\"eng-num\">25</span> “Oh, no! It’s out of the question!” said Kathy’s mother, firmly. “A designer’s advice is much <span class=\"eng-gap\"></span> than we can afford.” <span class=\"eng-word\">EXPENSIVE</span></p><p><span class=\"eng-num\">26</span> “Ok. It was just an idea.” “Getting back to the wall colour, why not make your room yellow or orange?” Dad suggested. “When the walls <span class=\"eng-gap\"></span> in those colours, the room will look cheerful.” <span class=\"eng-word\">PAINT</span></p><p><span class=\"eng-num\">27</span> “Yes!” Kathy definitely liked the idea. “We’ll make three walls yellow, but the <span class=\"eng-gap\"></span> one will be orange.” <span class=\"eng-word\">FOUR</span></p><p><span class=\"eng-num\">28</span> The next day, when Kathy came back from school, her Dad said: “Look what I<span class=\"eng-gap\"></span>.” There were paints and brushes on the floor. “Everything’s ready for us to start.” He smiled and handed Kathy the brush. <span class=\"eng-word\">BUY</span></p></div>",
