   "peek": "In 2010, a terrible earthquake hit the Haitian city of Léogâne. It was the … of January, my birthday. It was a normal day in the morning.",
   "text": "<div class=\"eng-text\"><p class=\"eng-note\">Прочитайте приведённый ниже текст. Преобразуйте слова, напечатанные заглавными буквами в конце строк, обозначенных номерами 20 – 28, так, чтобы они грамматически соответствовали содержанию текста. Заполните пропуски полученными словами. Каждый пропуск соответствует отдельному заданию 20 – 28.</p><p><span class=\"eng-num\">20</span> In 2010, a terrible earthquake hit the Haitian city of Léogâne. It was the <span class=\"eng-gap\"></span> of January, my birthday. It was a normal day in the morning. <span class=\"eng-word\">TWELVE</span></p><p><span class=\"eng-num\">21</span> I <span class=\"eng-gap\"></span> for my party when the earthquake hit. My first thought was that everybody was going to die. <span class=\"eng-word\">PREPARE</span></p><p><span class=\"eng-num\">22</span> I <span class=\"eng-gap\"></span> what was happening. <span class=\"eng-word\">NOT UNDERSTAND</span></p><p><span class=\"eng-num\">23</span> It was the <span class=\"eng-gap\"></span> day of my life so far – I have never felt that scared! After the earthquake I asked my wife: “How are we going to go on living?” <span class=\"eng-word\">BAD</span></p><p><span class=\"eng-num\">24</span> “I have no idea”, she said. “But we’re lucky. Our house is still standing, and thousands of people lost everything, even their <span class=\"eng-gap\"></span>”. <span class=\"eng-word\">LIFE</span></p><p><span class=\"eng-num\">25</span> She was right. We had to help the others, so we decided to start a charitable fund. At first we<span class=\"eng-gap\"></span> it the name of ‘Hope’ but then changed it. <span class=\"eng-word\">GIVE</span></p><p><span class=\"eng-num\">26</span> Now our fund <span class=\"eng-gap\"></span> ‘Seeds for Change’. <span class=\"eng-word\">CALL</span></p><p><span class=\"eng-num\">27</span> We work with small farmers and provide people from rural areas with everything necessary for farming. They say it helps them a lot. Their gratitude is the best award for <span class=\"eng-gap\"></span>. <span class=\"eng-word\">WE</span></p><p><span class=\"eng-num\">28</span> If we manage to involve more people in our fund, we <span class=\"eng-gap\"></span> more impressive results in the future. <span class=\"eng-word\">GET</span></p></div>",
