   "answerTex": "<br>20 — twelfth<br>21 — was preparing<br>22 — did not understand<br>23 — worst<br>24 — lives<br>25 — gave<br>26 — is called<br>27 — us<br>28 — will get",
   "steps": [
    "Текст с ответами:<div class=\"eng-text\"><p><span class=\"eng-num\">20</span> In 2010, a terrible earthquake hit the Haitian city of Léogâne. It was the <b>twelfth</b> of January, my birthday. It was a normal day in the morning.</p><p><span class=\"eng-num\">21</span> I <b>was preparing</b> for my party when the earthquake hit. My first thought was that everybody was going to die.</p><p><span class=\"eng-num\">22</span> I <b>did not understand</b> what was happening.</p><p><span class=\"eng-num\">23</span> It was the <b>worst</b> day of my life so far – I have never felt that scared! After the earthquake I asked my wife: “How are we going to go on living?”</p><p><span class=\"eng-num\">24</span> “I have no idea”, she said. “But we’re lucky. Our house is still standing, and thousands of people lost everything, even their <b>lives</b>”.</p><p><span class=\"eng-num\">25</span> She was right. We had to help the others, so we decided to start a charitable fund. At first we<b>gave</b> it the name of ‘Hope’ but then changed it.</p><p><span class=\"eng-num\">26</span> Now our fund <b>is called</b> ‘Seeds for Change’.</p><p><span class=\"eng-num\">27</span> We work with small farmers and provide people from rural areas with everything necessary for farming. They say it helps them a lot. Their gratitude is the best award for <b>us</b>.</p><p><span class=\"eng-num\">28</span> If we manage to involve more people in our fund, we <b>will get</b> more impressive results in the future.</p></div>"
   ],
