   "fipi": "3DF578, E8F201, BB1B8B, 81D9A8, 172E5E, 5E3F03, 017728, 2614D5, ED8126",
   "peek": "A robot is a special kind of machine that follows the instructions coming from a computer. A robot … mistakes and it never gets tired.",
   "text": "<div class=\"eng-text\"><p class=\"eng-note\">Прочитайте приведённый ниже текст. Преобразуйте слова, напечатанные заглавными буквами в конце строк, обозначенных номерами 20 – 28, так, чтобы они грамматически соответствовали содержанию текста. Заполните пропуски полученными словами. Каждый пропуск соответствует отдельному заданию 20 – 28.</p><p><span class=\"eng-num\">20</span> A robot is a special kind of machine that follows the instructions coming from a computer. A robot <span class=\"eng-gap\"></span> mistakes and it never gets tired. <span class=\"eng-word\">NOT MAKE</span></p><p><span class=\"eng-num\">21</span> Robots are all around <span class=\"eng-gap\"></span>. Robots make cars, explore dangerous places, clean things, answer telephone calls. <span class=\"eng-word\">WE</span></p><p><span class=\"eng-num\">22</span> Some of them can even take care of <span class=\"eng-gap\"></span> and elderly people. <span class=\"eng-word\">CHILD</span></p><p><span class=\"eng-num\">23</span> If we didn’t have robots, our life <span class=\"eng-gap\"></span> less comfortable and more dangerous. <span class=\"eng-word\">BE</span></p><p><span class=\"eng-num\">24</span> According to the dictionary, the word ‘robot’ <span class=\"eng-gap\"></span> ‘compulsory labour’. <span class=\"eng-word\">MEAN</span></p><p><span class=\"eng-num\">25</span> The word ‘robot’ <span class=\"eng-gap\"></span> for the first time in a science fiction play in 1920. <span class=\"eng-word\">USE</span></p><p><span class=\"eng-num\">26</span> The robot from that play was a destructive machine that finally<span class=\"eng-gap\"></span> the human race. <span class=\"eng-word\">DESTROY</span></p><p><span class=\"eng-num\">27</span> However, in real life, robots are still obedient to people. As for robots, the most enthusiastic nation is the Japanese. By now they <span class=\"eng-gap\"></span> a quarter of the world's robots. And they have very ambitious plans for the future. <span class=\"eng-word\">CREATE</span></p><p><span class=\"eng-num\">28</span> The Japanese engineers think that soon robots <span class=\"eng-gap\"></span> 3,5 million workers in their country. <span class=\"eng-word\">REPLACE</span></p></div>",
