   "text": "<div class=\"eng-text\"><p class=\"eng-note\">Прочитайте приведённый ниже текст. Преобразуйте слова, напечатанные заглавными буквами в конце строк, обозначенных номерами 20 – 28, так, чтобы они грамматически соответствовали содержанию текста. Заполните пропуски полученными словами. Каждый пропуск соответствует отдельному заданию 20 – 28.</p><p><span class=\"eng-num\">20</span> “What would you like me to bring you from London?” Dad often asked me this question when he was going somewhere on business. He worked a lot and <span class=\"eng-gap\"></span> a lot of time with the family. <span class=\"eng-word\">NOT SPEND</span></p><p><span class=\"eng-num\">21</span> We knew that he loved <span class=\"eng-gap\"></span> a lot but he was really a very busy person. <span class=\"eng-word\">WE</span></p><p><span class=\"eng-num\">22</span> And it was his <span class=\"eng-gap\"></span> business trip that month. <span class=\"eng-word\">THREE</span></p><p><span class=\"eng-num\">23</span> I thought for a moment and said: “I want a Paddington Bear.” My dad <span class=\"eng-gap\"></span> his suitcase but he looked up at me at once when he heard that. <span class=\"eng-word\">PACK</span></p><p><span class=\"eng-num\">24</span> He was surprised and asked me why I <span class=\"eng-gap\"></span> a Paddington Bear. <span class=\"eng-word\">WANT</span></p><p><span class=\"eng-num\">25</span> I didn’t know what to answer. My dad <span class=\"eng-gap\"></span> packing and sat down beside me. “You know, when I was small,” dad said quietly, “that bear was my favourite fictional character.” <span class=\"eng-word\">STOP</span></p><p><span class=\"eng-num\">26</span> I read the book too and I also saw a film about that character. He was a very polite bear who travelled to London from some exotic country. He <span class=\"eng-gap\"></span> in Paddington Station by the Brown family, who adopted him. <span class=\"eng-word\">DISCOVER</span></p><p><span class=\"eng-num\">27</span> The soft toy changed their life and made it much <span class=\"eng-gap\"></span>. <span class=\"eng-word\">GOOD</span></p><p><span class=\"eng-num\">28</span> “Ok. I <span class=\"eng-gap\"></span> you the bear if you want”, said Dad. “And we’ll also see the film about him as soon as I come back. Agreed?” “Sure.” I was delighted with his plan. <span class=\"eng-word\">BRING</span></p></div>",
