    "Текст с ответами:<div class=\"eng-text\"><p><span class=\"eng-num\">20</span> Mary’s birthday was on Saturday and she decided to arrange the party all by herself. At first, making a party to celebrate her <b>fifteenth</b> birthday looked like an easy thing to do.</p><p><span class=\"eng-num\">21</span> But when Mary started planning the event, a lot of questions came up. And the main problem was that she <b>did not know</b> what to start with!</p><p><span class=\"eng-num\">22</span> Mary called her cousin Vicki and asked if she <b>could</b> help with the arrangements.</p><p><span class=\"eng-num\">23</span> Vicki was a year <b>older</b> and more experienced in arranging parties. Vicki agreed and went to Mary’s house at once.</p><p><span class=\"eng-num\">24</span> When Vicki arrived, Mary <b>was designing</b> a menu for the party.</p><p><span class=\"eng-num\">25</span> Vicki looked at the draft of the menu and <b>told</b> Mary that her approach was totally wrong.</p><p><span class=\"eng-num\">26</span> “We shouldn’t start with the menu,” she said, “We should start with the list of guests and with the programme for the event. You <b>have decided</b> who you want to invite to your party, haven’t you?” “No,” answered Mary, “I haven’t.”</p><p><span class=\"eng-num\">27</span> It took the girls half an hour to make a list of guests. Each name <b>was written</b> carefully on glossy paper.</p><p><span class=\"eng-num\">28</span> “It looks fine,” said Vicki, “But there are too many of <b>them</b>. Don’t you think so?”</p></div>"
