   "fipi": "2BB171, 56267F, 61D5B0, 375105, CD5351, F563CA, 9ABD1C, 9E33F9, 9494A2",
   "peek": "Most people love jokes. A good joke can break the ice and make the conversation enjoyable. My friend’s hobby is collecting jokes. When he … a good joke, he writes it down on a special card.",
   "text": "<div class=\"eng-text\"><p class=\"eng-note\">Прочитайте приведённый ниже текст. Преобразуйте слова, напечатанные заглавными буквами в конце строк, обозначенных номерами 20 – 28, так, чтобы они грамматически соответствовали содержанию текста. Заполните пропуски полученными словами. Каждый пропуск соответствует отдельному заданию 20 – 28.</p><p><span class=\"eng-num\">20</span> Most people love jokes. A good joke can break the ice and make the conversation enjoyable. My friend’s hobby is collecting jokes. When he <span class=\"eng-gap\"></span> a good joke, he writes it down on a special card. <span class=\"eng-word\">HEAR</span></p><p><span class=\"eng-num\">21</span> The cards <span class=\"eng-gap\"></span> in a box in his room. <span class=\"eng-word\">KEEP</span></p><p><span class=\"eng-num\">22</span> When I visit <span class=\"eng-gap\"></span>, I never miss a chance to read a joke from his collection. Yesterday’s joke was about famous detectives. Here it is. <span class=\"eng-word\">HE</span></p><p><span class=\"eng-num\">23</span> One day Sherlock Holmes and Dr Watson went camping. They put up a tent, made a fire and had a good dinner of meat and <span class=\"eng-gap\"></span>. <span class=\"eng-word\">POTATO</span></p><p><span class=\"eng-num\">24</span> That night, Holmes <span class=\"eng-gap\"></span> up and asked: “Watson, look up and tell me what you see.” <span class=\"eng-word\">WAKE</span></p><p><span class=\"eng-num\">25</span> Watson said that he <span class=\"eng-gap\"></span> millions of stars. “And what does it tell you?” Holmes went on his interrogation. <span class=\"eng-word\">SEE</span></p><p><span class=\"eng-num\">26</span> “Well, if we apply our deductive method, we’ll come to several conclusions. Astronomically, there are billions of planets. My<span class=\"eng-gap\"></span> conclusion is astrological – I observe Saturn in Leo. <span class=\"eng-word\">TWO</span></p><p><span class=\"eng-num\">27</span> And, meteorologically, it’ll be a beautiful day tomorrow. I wish we<span class=\"eng-gap\"></span> this kind of weather more often in this country. And what does the sky tell you, Holmes?” <span class=\"eng-word\">HAVE</span></p><p><span class=\"eng-num\">28</span> Holmes was silent for a moment and then said, “Someone <span class=\"eng-gap\"></span> our tent!” <span class=\"eng-word\">STEAL</span></p></div>",
