   "text": "<div class=\"eng-text\"><p class=\"eng-note\">Прочитайте приведённый ниже текст. Преобразуйте слова, напечатанные заглавными буквами в конце строк, обозначенных номерами 20 – 28, так, чтобы они грамматически соответствовали содержанию текста. Заполните пропуски полученными словами. Каждый пропуск соответствует отдельному заданию 20 – 28.</p><p><span class=\"eng-num\">20</span> Paul was going to be late for his morning class again. He <span class=\"eng-gap\"></span> why it happened to him so often. <span class=\"eng-word\">NOT UNDERSTAND</span></p><p><span class=\"eng-num\">21</span> This was going to be the <span class=\"eng-gap\"></span> time in one week and that was too much even for Mrs Pitt. <span class=\"eng-word\">THREE</span></p><p><span class=\"eng-num\">22</span> She was the <span class=\"eng-gap\"></span> teacher in the world but Paul wasn’t sure that she would forgive him again. <span class=\"eng-word\">KIND</span></p><p><span class=\"eng-num\">23</span> “If I don’t invent a very good excuse, she <span class=\"eng-gap\"></span> my parents.” Paul thought. <span class=\"eng-word\">CALL</span></p><p><span class=\"eng-num\">24</span> His parents <span class=\"eng-gap\"></span> very strict people but they didn’t approve of Paul’s habit of playing computer games till late at night. <span class=\"eng-word\">NOT BE</span></p><p><span class=\"eng-num\">25</span> As a result, he couldn’t make himself get up in the morning and <span class=\"eng-gap\"></span> regularly late for school. <span class=\"eng-word\">BE</span></p><p><span class=\"eng-num\">26</span> Paul quietly opened the door and <span class=\"eng-gap\"></span> into the classroom. <span class=\"eng-word\">GO</span></p><p><span class=\"eng-num\">27</span> His classmates <span class=\"eng-gap\"></span> something in their notepads and didn’t pay any attention to him. <span class=\"eng-word\">WRITE</span></p><p><span class=\"eng-num\">28</span> Mrs Pitt looked at him and said in a flat voice: “You are late again, Paul. What <span class=\"eng-gap\"></span>?” Paul was not ready with an answer. <span class=\"eng-word\">HAPPEN</span></p></div>",
