   "fipi": "53F086, 0885E6, 791FF2, 35881A, AA8F98, B26B6E, C058C2, 8400CE, 859B6E",
   "peek": "Lucky, a big black cat, went missing shortly after our family moved to a new house. He was curious and enjoyed exploring the environment. It often made us worry about ….",
   "text": "<div class=\"eng-text\"><p class=\"eng-note\">Прочитайте приведённый ниже текст. Преобразуйте слова, напечатанные заглавными буквами в конце строк, обозначенных номерами 20 – 28, так, чтобы они грамматически соответствовали содержанию текста. Заполните пропуски полученными словами. Каждый пропуск соответствует отдельному заданию 20 – 28.</p><p><span class=\"eng-num\">20</span> Lucky, a big black cat, went missing shortly after our family moved to a new house. He was curious and enjoyed exploring the environment. It often made us worry about <span class=\"eng-gap\"></span>. <span class=\"eng-word\">HE</span></p><p><span class=\"eng-num\">21</span> Mum often said “I wish our Lucky <span class=\"eng-gap\"></span> less curious. I feel better when he is in the house, safe and lazy.” <span class=\"eng-word\">BE</span></p><p><span class=\"eng-num\">22</span> As we <span class=\"eng-gap\"></span> keep him at home, we made him wear a special tag. <span class=\"eng-word\">NOT CAN</span></p><p><span class=\"eng-num\">23</span> Our address <span class=\"eng-gap\"></span> on it in large printed letters. <span class=\"eng-word\">WRITE</span></p><p><span class=\"eng-num\">24</span> Mum said: “If one day Lucky gets missing, the tag <span class=\"eng-gap\"></span> us find him”. <span class=\"eng-word\">HELP</span></p><p><span class=\"eng-num\">25</span> Lucky disappeared on the <span class=\"eng-gap\"></span> day after moving house. We looked for the cat everywhere. We asked all our new neighbours about him. <span class=\"eng-word\">THREE</span></p><p><span class=\"eng-num\">26</span> We even asked all the <span class=\"eng-gap\"></span> in our district if they had seen him. But nobody had seen a cat that looked like our Lucky. <span class=\"eng-word\">POLICEMAN</span></p><p><span class=\"eng-num\">27</span> In the end, we <span class=\"eng-gap\"></span> hope. Two weeks later I was passing by our old house. On the porch there was a cat that looked strikingly like Lucky. And it was Lucky! <span class=\"eng-word\">LOSE</span></p><p><span class=\"eng-num\">28</span> I grabbed him and brought him home. “Mum, look who I <span class=\"eng-gap\"></span>!” I cried to mum. “The new owner told me the cat had been waiting for us in our old house. Nobody could inform us about him because the address on the cat’s tag is our old address.” <span class=\"eng-word\">FIND</span></p></div>",
