   "text": "<div class=\"eng-text\"><p class=\"eng-note\">Прочитайте приведённый ниже текст. Преобразуйте слова, напечатанные заглавными буквами в конце строк, обозначенных номерами 20 – 28, так, чтобы они грамматически соответствовали содержанию текста. Заполните пропуски полученными словами. Каждый пропуск соответствует отдельному заданию 20 – 28.</p><p><span class=\"eng-num\">20</span> I come from England but now I live permanently in Québec, Canada. When my parents <span class=\"eng-gap\"></span> me to Canada, I was fifteen. <span class=\"eng-word\">BRING</span></p><p><span class=\"eng-num\">21</span> It was winter and I <span class=\"eng-gap\"></span> by the amount of snow there. <span class=\"eng-word\">IMPRESS</span></p><p><span class=\"eng-num\">22</span> I asked my new friends what they usually <span class=\"eng-gap\"></span> for entertainment in such a cold climate. <span class=\"eng-word\">DO</span></p><p><span class=\"eng-num\">23</span> Their answer was simple, “In winter <span class=\"eng-gap\"></span> and adults go skiing and skating.” Before arriving in Canada I had never tried skating and my Canadian ice experience was really painful. <span class=\"eng-word\">CHILD</span></p><p><span class=\"eng-num\">24</span> To start with, it took <span class=\"eng-gap\"></span> half an hour to put on the skates. <span class=\"eng-word\">I</span></p><p><span class=\"eng-num\">25</span> I <span class=\"eng-gap\"></span> how to move so my new friends showed me some basic techniques. <span class=\"eng-word\">NOT KNOW</span></p><p><span class=\"eng-num\">26</span> However, when I was left alone on the ice, I <span class=\"eng-gap\"></span> over immediately. When I opened my eyes, my new friends were standing around. They weren’t laughing, they looked worried. <span class=\"eng-word\">FALL</span></p><p><span class=\"eng-num\">27</span> “Are you OK?” they asked. “Fine,” I said, “I wish I <span class=\"eng-gap\"></span> skate as easily as you do.” <span class=\"eng-word\">CAN</span></p><p><span class=\"eng-num\">28</span> “You definitely will,” they smiled. And they were right. By the end of my <span class=\"eng-gap\"></span> winter in Canada, I felt confident on the ice. More than that, I found out that skating was a really exciting activity! <span class=\"eng-word\">ONE</span></p></div>",
