   "answerTex": "<br>20 — brought<br>21 — was impressed<br>22 — did<br>23 — children<br>24 — me<br>25 — did not know<br>26 — fell<br>27 — could<br>28 — first",
   "steps": [
    "Текст с ответами:<div class=\"eng-text\"><p><span class=\"eng-num\">20</span> I come from England but now I live permanently in Québec, Canada. When my parents <b>brought</b> me to Canada, I was fifteen.</p><p><span class=\"eng-num\">21</span> It was winter and I <b>was impressed</b> by the amount of snow there.</p><p><span class=\"eng-num\">22</span> I asked my new friends what they usually <b>did</b> for entertainment in such a cold climate.</p><p><span class=\"eng-num\">23</span> Their answer was simple, “In winter <b>children</b> and adults go skiing and skating.” Before arriving in Canada I had never tried skating and my Canadian ice experience was really painful.</p><p><span class=\"eng-num\">24</span> To start with, it took <b>me</b> half an hour to put on the skates.</p><p><span class=\"eng-num\">25</span> I <b>did not know</b> how to move so my new friends showed me some basic techniques.</p><p><span class=\"eng-num\">26</span> However, when I was left alone on the ice, I <b>fell</b> over immediately. When I opened my eyes, my new friends were standing around. They weren’t laughing, they looked worried.</p><p><span class=\"eng-num\">27</span> “Are you OK?” they asked. “Fine,” I said, “I wish I <b>could</b> skate as easily as you do.”</p><p><span class=\"eng-num\">28</span> “You definitely will,” they smiled. And they were right. By the end of my <b>first</b> winter in Canada, I felt confident on the ice. More than that, I found out that skating was a really exciting activity!</p></div>"
   ],
