   "fipi": "180647, 1E5B1E, 964D30, 862770, 9BA5BC, FA9F96, E551F5, 15159E, BBBA44",
   "peek": "When I was little, I loved reading books written by Roald Dahl. They were my favourite choice of bedtime story. When Mum asked me what book I wanted, I always… a book by Dahl.",
   "text": "<div class=\"eng-text\"><p class=\"eng-note\">Прочитайте приведённый ниже текст. Преобразуйте слова, напечатанные заглавными буквами в конце строк, обозначенных номерами 20 – 28, так, чтобы они грамматически соответствовали содержанию текста. Заполните пропуски полученными словами. Каждый пропуск соответствует отдельному заданию 20 – 28.</p><p><span class=\"eng-num\">20</span> When I was little, I loved reading books written by Roald Dahl. They were my favourite choice of bedtime story. When Mum asked me what book I wanted, I always<span class=\"eng-gap\"></span> a book by Dahl. <span class=\"eng-word\">CHOOSE</span></p><p><span class=\"eng-num\">21</span> Mum readily agreed. She said she <span class=\"eng-gap\"></span> reading him too in spite of the fact that she was an adult and had a very serious job. <span class=\"eng-word\">ENJOY</span></p><p><span class=\"eng-num\">22</span> In those years there <span class=\"eng-gap\"></span> lots of Dahl’s books in our home library. <span class=\"eng-word\">BE</span></p><p><span class=\"eng-num\">23</span> And to me he is still the best children’s author of the <span class=\"eng-gap\"></span> century. <span class=\"eng-word\">TWENTY</span></p><p><span class=\"eng-num\">24</span> Roald Dahl started as an adult writer. His first book <span class=\"eng-gap\"></span> in 1942. <span class=\"eng-word\">PUBLISH</span></p><p><span class=\"eng-num\">25</span> Later he began writing children’s books. Many of the <span class=\"eng-gap\"></span> are based on Dahl’s own childhood memories. <span class=\"eng-word\">STORY</span></p><p><span class=\"eng-num\">26</span> Several of his books are now successful films, for example ‘Matilda’, ‘Charlie and the Chocolate Factory’ and ‘Fantastic Mr Fox’. I’m sure you <span class=\"eng-gap\"></span> at least one of them! <span class=\"eng-word\">SEE</span></p><p><span class=\"eng-num\">27</span> When you shop for children’s books, Dahl is the <span class=\"eng-gap\"></span> choice. His books are entertaining and full of jokes. <span class=\"eng-word\">EASY</span></p><p><span class=\"eng-num\">28</span> Roald Dahl is an author that you can never grow tired of. Now I read his books to <span class=\"eng-gap\"></span> son. He is too small yet and cannot read himself. <span class=\"eng-word\">I</span></p></div>",
