   "fipi": "DD645D, BB8EAA, 80FDD3, A4BE2F, F1AAF2, E5A861, A17FBD, 64B82A, FE39E7",
   "peek": "Most adults miss their childhood. Your school years are the … years of your life, they say.",
   "text": "<div class=\"eng-text\"><p class=\"eng-note\">Прочитайте приведённый ниже текст. Преобразуйте слова, напечатанные заглавными буквами в конце строк, обозначенных номерами 20 – 28, так, чтобы они грамматически соответствовали содержанию текста. Заполните пропуски полученными словами. Каждый пропуск соответствует отдельному заданию 20 – 28.</p><p><span class=\"eng-num\">20</span> Most adults miss their childhood. Your school years are the <span class=\"eng-gap\"></span> years of your life, they say. <span class=\"eng-word\">GOOD</span></p><p><span class=\"eng-num\">21</span> Just recently, while I was on my way to work, I started thinking back to my own school years. They probably were not trouble-free but there <span class=\"eng-gap\"></span> many reasons for us to feel happy at school. <span class=\"eng-word\">BE</span></p><p><span class=\"eng-num\">22</span> One of them was spending every single day with friends. We <span class=\"eng-gap\"></span> tired of being together. <span class=\"eng-word\">NOT GET</span></p><p><span class=\"eng-num\">23</span> The <span class=\"eng-gap\"></span> one was uniform. Yes, in my opinion, the school uniform had more advantages than disadvantages. <span class=\"eng-word\">TWO</span></p><p><span class=\"eng-num\">24</span> It was dark green, unfashionable but comfortable. It <span class=\"eng-gap\"></span> of natural materials. <span class=\"eng-word\">MAKE</span></p><p><span class=\"eng-num\">25</span> Besides, the uniform <span class=\"eng-gap\"></span> a lot of time in the mornings. <span class=\"eng-word\">SAVE</span></p><p><span class=\"eng-num\">26</span> Now it <span class=\"eng-gap\"></span> me hours to decide what to wear. <span class=\"eng-word\">TAKE</span></p><p><span class=\"eng-num\">27</span> Another thing is that I don’t really like sport. But at school we <span class=\"eng-gap\"></span> football, netball, hockey and so on. Sport was compulsory. Now I realise that this was a good thing! <span class=\"eng-word\">PLAY</span></p><p><span class=\"eng-num\">28</span> And of course there were… holidays! Christmas, Easter, half-term, and the jackpot – the summer holidays. I wish I <span class=\"eng-gap\"></span> as much free time now. <span class=\"eng-word\">HAVE</span></p></div>",
