   "text": "<div class=\"eng-text\"><p class=\"eng-note\">Прочитайте приведённый ниже текст. Преобразуйте слова, напечатанные заглавными буквами в конце строк, обозначенных номерами 20 – 28, так, чтобы они грамматически соответствовали содержанию текста. Заполните пропуски полученными словами. Каждый пропуск соответствует отдельному заданию 20 – 28.</p><p><span class=\"eng-num\">20</span> This story happened long ago. My son was six and we lived in an old house near a large park. There <span class=\"eng-gap\"></span> lots of people in the park at weekends and we enjoyed walking and playing there too. <span class=\"eng-word\">BE</span></p><p><span class=\"eng-num\">21</span> One day, my son <span class=\"eng-gap\"></span> an injured bird from the park. <span class=\"eng-word\">BRING</span></p><p><span class=\"eng-num\">22</span> It was a crow. Its wing <span class=\"eng-gap\"></span> and the bird could not fly. <span class=\"eng-word\">BREAK</span></p><p><span class=\"eng-num\">23</span> I didn’t know what to do with the crow, but my son said that he <span class=\"eng-gap\"></span> care of it. <span class=\"eng-word\">TAKE</span></p><p><span class=\"eng-num\">24</span> “If you were a couple of years<span class=\"eng-gap\"></span>, you could manage it. But I doubt you can do it now,” I tried to talk him out of keeping the crow but finally agreed to take the bird home. <span class=\"eng-word\">OLD</span></p><p><span class=\"eng-num\">25</span> The next day we took the crow to the vet. The vet fixed and bandaged the wing and explained to <span class=\"eng-gap\"></span> what medicines we should give to the bird. <span class=\"eng-word\">WE</span></p><p><span class=\"eng-num\">26</span> “Ok,” he said, as we left, “I <span class=\"eng-gap\"></span> everything I can. There’s no need to bring this crow here any more. <span class=\"eng-word\">DO</span></p><p><span class=\"eng-num\">27</span> The bird is young and strong, and I think it <span class=\"eng-gap\"></span> soon. This is the good news. The bad news is that it will never be able to fly again.” <span class=\"eng-word\">RECOVER</span></p><p><span class=\"eng-num\">28</span> “We’ll see,” my son <span class=\"eng-gap\"></span> to agree with this fact too easily. <span class=\"eng-word\">NOT WANT</span></p></div>",
