   "answerTex": "<br>20 — were<br>21 — brought<br>22 — was broken<br>23 — would take<br>24 — older<br>25 — us<br>26 — have done<br>27 — will recover<br>28 — did not want",
   "steps": [
    "Текст с ответами:<div class=\"eng-text\"><p><span class=\"eng-num\">20</span> This story happened long ago. My son was six and we lived in an old house near a large park. There <b>were</b> lots of people in the park at weekends and we enjoyed walking and playing there too.</p><p><span class=\"eng-num\">21</span> One day, my son <b>brought</b> an injured bird from the park.</p><p><span class=\"eng-num\">22</span> It was a crow. Its wing <b>was broken</b> and the bird could not fly.</p><p><span class=\"eng-num\">23</span> I didn’t know what to do with the crow, but my son said that he <b>would take</b> care of it.</p><p><span class=\"eng-num\">24</span> “If you were a couple of years<b>older</b>, you could manage it. But I doubt you can do it now,” I tried to talk him out of keeping the crow but finally agreed to take the bird home.</p><p><span class=\"eng-num\">25</span> The next day we took the crow to the vet. The vet fixed and bandaged the wing and explained to <b>us</b> what medicines we should give to the bird.</p><p><span class=\"eng-num\">26</span> “Ok,” he said, as we left, “I <b>have done</b> everything I can. There’s no need to bring this crow here any more.</p><p><span class=\"eng-num\">27</span> The bird is young and strong, and I think it <b>will recover</b> soon. This is the good news. The bad news is that it will never be able to fly again.”</p><p><span class=\"eng-num\">28</span> “We’ll see,” my son <b>did not want</b> to agree with this fact too easily.</p></div>"
   ],
