   "answerTex": "<br>20 — second<br>21 — has happened (или happened)<br>22 — me<br>23 — will not take<br>24 — women<br>25 — became<br>26 — wanted<br>27 — was<br>28 — most popular",
   "steps": [
    "Текст с ответами:<div class=\"eng-text\"><p><span class=\"eng-num\">20</span> Kate called me early in the morning. It was the <b>second</b> day of holidays; I felt angry with her for waking me up.</p><p><span class=\"eng-num\">21</span> “What <b>has happened</b>?” I didn’t sound very polite, but she paid no attention to that.</p><p><span class=\"eng-num\">22</span> “Oh, nothing! I want to go shopping today and wondered if you wanted to go with <b>me</b>.”</p><p><span class=\"eng-num\">23</span> “No, I don’t want to.” “But it <b>will not take</b> you long! I promise”.</p><p><span class=\"eng-num\">24</span> My first impulse was to say “no” – unlike most <b>women</b> I hated shopping. But Kate sounded so unhappy that I felt sorry for her.</p><p><span class=\"eng-num\">25</span> “Ok, what do you need to buy?” Kate’s voice <b>became</b> cheerful again.</p><p><span class=\"eng-num\">26</span> She excitedly explained to me that she <b>wanted</b> to buy a pair of hiking boots and a raincoat.</p><p><span class=\"eng-num\">27</span> That <b>was</b> strange as Kate had never been fond of hiking. “I want to take up hiking as a new hobby,” went on Kate. “Bob Smith says that it’s really exciting.”</p><p><span class=\"eng-num\">28</span> Now I knew what was going on. Bob Smith, the captain of the school baseball team, was the <b>most popular</b> boy in our school. All the girls wanted to attract his attention.</p></div>"
   ],
