   "fipi": "0BF77E, 07CE5C, AEFE73, FCFE7E, 316EAC, 671357, 762D50, F3B90F, 67E2DA",
   "peek": "I’m studying Italian in a summer school in Tuscany. I arrived a few days ago. It’s my … trip to Italy.",
   "text": "<div class=\"eng-text\"><p class=\"eng-note\">Прочитайте приведённый ниже текст. Преобразуйте слова, напечатанные заглавными буквами в конце строк, обозначенных номерами 20 – 28, так, чтобы они грамматически соответствовали содержанию текста. Заполните пропуски полученными словами. Каждый пропуск соответствует отдельному заданию 20 – 28.</p><p><span class=\"eng-num\">20</span> I’m studying Italian in a summer school in Tuscany. I arrived a few days ago. It’s my <span class=\"eng-gap\"></span> trip to Italy. <span class=\"eng-word\">ONE</span></p><p><span class=\"eng-num\">21</span> I like this country very much though I <span class=\"eng-gap\"></span> its main tourist attractions yet. <span class=\"eng-word\">NOT SEE</span></p><p><span class=\"eng-num\">22</span> Actually it was my mum’s idea to send me here. In her opinion Italy is the <span class=\"eng-gap\"></span> country in the world. <span class=\"eng-word\">INTERESTING</span></p><p><span class=\"eng-num\">23</span> And she also said that it <span class=\"eng-gap\"></span> me improve my Italian in real-life communication. <span class=\"eng-word\">HELP</span></p><p><span class=\"eng-num\">24</span> Yesterday, while I <span class=\"eng-gap\"></span> dinner in the cafeteria, four other students sat at the same table. We got acquainted. Two of them were Argentines, then a Russian and a Greek. A mix of cultures! <span class=\"eng-word\">HAVE</span></p><p><span class=\"eng-num\">25</span> We started chatting in Italian, laughing, telling jokes and sharing our life<span class=\"eng-gap\"></span>. It was lots of fun. I even started to speak Spanish with the Argentines, and our sentences became a mixture of both Italian and Spanish. <span class=\"eng-word\">STORY</span></p><p><span class=\"eng-num\">26</span> But it did not matter at all! No problem. We easily <span class=\"eng-gap\"></span> each other. <span class=\"eng-word\">UNDERSTAND</span></p><p><span class=\"eng-num\">27</span> I wish all people <span class=\"eng-gap\"></span> foreign languages. The more languages you know – the better. <span class=\"eng-word\">SPEAK</span></p><p><span class=\"eng-num\">28</span> Languages help <span class=\"eng-gap\"></span> understand the culture and mentality of other people. <span class=\"eng-word\">WE</span></p></div>",
