   "answerTex": "<br>20 — first<br>21 — have not seen<br>22 — most interesting<br>23 — would help<br>24 — was having<br>25 — stories<br>26 — understood<br>27 — spoke<br>28 — us",
   "steps": [
    "Текст с ответами:<div class=\"eng-text\"><p><span class=\"eng-num\">20</span> I’m studying Italian in a summer school in Tuscany. I arrived a few days ago. It’s my <b>first</b> trip to Italy.</p><p><span class=\"eng-num\">21</span> I like this country very much though I <b>have not seen</b> its main tourist attractions yet.</p><p><span class=\"eng-num\">22</span> Actually it was my mum’s idea to send me here. In her opinion Italy is the <b>most interesting</b> country in the world.</p><p><span class=\"eng-num\">23</span> And she also said that it <b>would help</b> me improve my Italian in real-life communication.</p><p><span class=\"eng-num\">24</span> Yesterday, while I <b>was having</b> dinner in the cafeteria, four other students sat at the same table. We got acquainted. Two of them were Argentines, then a Russian and a Greek. A mix of cultures!</p><p><span class=\"eng-num\">25</span> We started chatting in Italian, laughing, telling jokes and sharing our life<b>stories</b>. It was lots of fun. I even started to speak Spanish with the Argentines, and our sentences became a mixture of both Italian and Spanish.</p><p><span class=\"eng-num\">26</span> But it did not matter at all! No problem. We easily <b>understood</b> each other.</p><p><span class=\"eng-num\">27</span> I wish all people <b>spoke</b> foreign languages. The more languages you know – the better.</p><p><span class=\"eng-num\">28</span> Languages help <b>us</b> understand the culture and mentality of other people.</p></div>"
   ],
