   "fipi": "167A06, 444980, 0BE0D6, 54C867, C0EFB1, CF163A, 5398D1, 583096, A489C1",
   "peek": "Have you heard of Band Aid 30? Probably not. Then let me explain what ‘Band Aid’ is. In 1984, Bob Geldof and Midge Ure … together a group of British and Irish singers and musicians and produced a song, called ‘Do They Know It’s Christmas?’.",
   "text": "<div class=\"eng-text\"><p class=\"eng-note\">Прочитайте приведённый ниже текст. Преобразуйте слова, напечатанные заглавными буквами в конце строк, обозначенных номерами 20 – 28, так, чтобы они грамматически соответствовали содержанию текста. Заполните пропуски полученными словами. Каждый пропуск соответствует отдельному заданию 20 – 28.</p><p><span class=\"eng-num\">20</span> Have you heard of Band Aid 30? Probably not. Then let me explain what ‘Band Aid’ is. In 1984, Bob Geldof and Midge Ure <span class=\"eng-gap\"></span> together a group of British and Irish singers and musicians and produced a song, called ‘Do They Know It’s Christmas?’. <span class=\"eng-word\">BRING</span></p><p><span class=\"eng-num\">21</span> The song was a charity single. The musicians said that the money from the sales <span class=\"eng-gap\"></span> to help poor people in Ethiopia, who were suffering from a famine. <span class=\"eng-word\">GO</span></p><p><span class=\"eng-num\">22</span> The group <span class=\"eng-gap\"></span> Band Aid. Over forty singers were involved in the project, including Paul McCartney, Bono, David Bowie and Sting. <span class=\"eng-word\">CALL</span></p><p><span class=\"eng-num\">23</span> In 2014, the group changed its name to ‘Band Aid 30’ because it was the <span class=\"eng-gap\"></span> time the song was recorded. That year, the song aimed to help those who were suffering from the Ebola virus. <span class=\"eng-word\">THIRTY</span></p><p><span class=\"eng-num\">24</span> Since the time of its birth, the song <span class=\"eng-gap\"></span> a lot of money. The money is still used only for charity. <span class=\"eng-word\">MAKE</span></p><p><span class=\"eng-num\">25</span> Although the song has sometimes been criticised, over 312,000 <span class=\"eng-gap\"></span> of the song have been sold. <span class=\"eng-word\">COPY</span></p><p><span class=\"eng-num\">26</span> Usually, I <span class=\"eng-gap\"></span> to music a lot, I have other hobbies. <span class=\"eng-word\">NOT LISTEN</span></p><p><span class=\"eng-num\">27</span> But one of my friends, who is a <span class=\"eng-gap\"></span> music expert than I am, says that, if the song helps people in need – it can never be a bad thing! <span class=\"eng-word\">GREAT</span></p><p><span class=\"eng-num\">28</span> I agree with <span class=\"eng-gap\"></span>. <span class=\"eng-word\">HE</span></p></div>",
