   "answerTex": "<br>20 — brought<br>21 — would go<br>22 — was called<br>23 — thirtieth<br>24 — has made<br>25 — copies<br>26 — do not listen<br>27 — greater<br>28 — him",
   "steps": [
    "Текст с ответами:<div class=\"eng-text\"><p><span class=\"eng-num\">20</span> Have you heard of Band Aid 30? Probably not. Then let me explain what ‘Band Aid’ is. In 1984, Bob Geldof and Midge Ure <b>brought</b> together a group of British and Irish singers and musicians and produced a song, called ‘Do They Know It’s Christmas?’.</p><p><span class=\"eng-num\">21</span> The song was a charity single. The musicians said that the money from the sales <b>would go</b> to help poor people in Ethiopia, who were suffering from a famine.</p><p><span class=\"eng-num\">22</span> The group <b>was called</b> Band Aid. Over forty singers were involved in the project, including Paul McCartney, Bono, David Bowie and Sting.</p><p><span class=\"eng-num\">23</span> In 2014, the group changed its name to ‘Band Aid 30’ because it was the <b>thirtieth</b> time the song was recorded. That year, the song aimed to help those who were suffering from the Ebola virus.</p><p><span class=\"eng-num\">24</span> Since the time of its birth, the song <b>has made</b> a lot of money. The money is still used only for charity.</p><p><span class=\"eng-num\">25</span> Although the song has sometimes been criticised, over 312,000 <b>copies</b> of the song have been sold.</p><p><span class=\"eng-num\">26</span> Usually, I <b>do not listen</b> to music a lot, I have other hobbies.</p><p><span class=\"eng-num\">27</span> But one of my friends, who is a <b>greater</b> music expert than I am, says that, if the song helps people in need – it can never be a bad thing!</p><p><span class=\"eng-num\">28</span> I agree with <b>him</b>.</p></div>"
   ],
