   "text": "<div class=\"eng-text\"><p class=\"eng-note\">Прочитайте приведённый ниже текст. Преобразуйте слова, напечатанные заглавными буквами в конце строк, обозначенных номерами 20 – 28, так, чтобы они грамматически соответствовали содержанию текста. Заполните пропуски полученными словами. Каждый пропуск соответствует отдельному заданию 20 – 28.</p><p><span class=\"eng-num\">20</span> The phone rang in Clark Taylor’s house at nearly three in the morning. He answered it only after the <span class=\"eng-gap\"></span> ring. “Hello,” Clark said in a sleepy voice. <span class=\"eng-word\">FIVE</span></p><p><span class=\"eng-num\">21</span> “Mr. Taylor. Thank goodness. I need your help.” Clark definitely <span class=\"eng-gap\"></span> the voice. <span class=\"eng-word\">KNOW</span></p><p><span class=\"eng-num\">22</span> However, he was sleepy and <span class=\"eng-gap\"></span> remember who it was. <span class=\"eng-word\">NOT CAN</span></p><p><span class=\"eng-num\">23</span> “Mr. Taylor!” the man said. “I am in trouble. The police allowed me only one phone call. And I am calling you.” Then, the fog cleared. Although nearly ten years had passed since <span class=\"eng-gap\"></span> last meeting, Clark was able to recognise the voice. <span class=\"eng-word\">THEY</span></p><p><span class=\"eng-num\">24</span> It belonged to Martin Hall, one of the <span class=\"eng-gap\"></span> math students he had ever had. <span class=\"eng-word\">BRIGHT</span></p><p><span class=\"eng-num\">25</span> “Martin, what’s happened? Where are you? ” Clark asked. “In the police station. I <span class=\"eng-gap\"></span> at the railway station two hours ago. I was going to a conference. <span class=\"eng-word\">ARREST</span></p><p><span class=\"eng-num\">26</span> The police mistook me for another person. The irony is that I really do look like the criminal that they are looking for. Besides that, I <span class=\"eng-gap\"></span> my ID card and I can’t prove who I am. You are the only person in this town who knows me. Can you help me?” Martin Hall asked. <span class=\"eng-word\">LOSE</span></p><p><span class=\"eng-num\">27</span> “If you give me the address, I <span class=\"eng-gap\"></span> at once,” Clark said, jumping up of the bed. <span class=\"eng-word\">COME</span></p><p><span class=\"eng-num\">28</span> It was not difficult for him to prove that Martin Hall was his former student. Clark brought a scientific journal with Martin’s article and a photo of him. The <span class=\"eng-gap\"></span> were surprised to find out that their prisoner was a capable young scientist. <span class=\"eng-word\">POLICEMAN</span></p></div>",
