   "text": "<div class=\"eng-text\"><p class=\"eng-note\">Прочитайте приведённый ниже текст. Преобразуйте слова, напечатанные заглавными буквами в конце строк, обозначенных номерами 20 – 28, так, чтобы они грамматически соответствовали содержанию текста. Заполните пропуски полученными словами. Каждый пропуск соответствует отдельному заданию 20 – 28.</p><p><span class=\"eng-num\">20</span> By today’s standards, my mobile phone is pretty basic. It’s a Nokia. It’s a small device that receives telephone calls and sends text messages. Other than that, my phone <span class=\"eng-gap\"></span> much. <span class=\"eng-word\">NOT DO</span></p><p><span class=\"eng-num\">21</span> Most of my friends wish they <span class=\"eng-gap\"></span> smartphones because they are cool and trendy. <span class=\"eng-word\">HAVE</span></p><p><span class=\"eng-num\">22</span> They say the <span class=\"eng-gap\"></span> thing about a smartphone is that you ‘can do everything with it!’ <span class=\"eng-word\">GOOD</span></p><p><span class=\"eng-num\">23</span> That’s right, smartphones have many more functions than a simple phone, however, not all of them are needed. In everyday life, smartphones <span class=\"eng-gap\"></span> mainly for checking social networking sites, replying to emails, and playing games. <span class=\"eng-word\">USE</span></p><p><span class=\"eng-num\">24</span> Grown-ups as well as <span class=\"eng-gap\"></span> like playing games. <span class=\"eng-word\">CHILD</span></p><p><span class=\"eng-num\">25</span> Anyway, I prefer my good old Nokia. It’s my <span class=\"eng-gap\"></span> mobile phone. <span class=\"eng-word\">ONE</span></p><p><span class=\"eng-num\">26</span> When I bought it, it didn’t cost <span class=\"eng-gap\"></span> very much. And I am not afraid anyone will ever steal it. <span class=\"eng-word\">I</span></p><p><span class=\"eng-num\">27</span> It’s also very reliable. Yesterday I dropped it. It <span class=\"eng-gap\"></span> down the staircase and hit the wall. <span class=\"eng-word\">FLY</span></p><p><span class=\"eng-num\">28</span> I thought that <span class=\"eng-gap\"></span> the end of it. But nothing of the kind – it still works properly! <span class=\"eng-word\">BE</span></p></div>",
