   "answerTex": "<br>20 — does not do<br>21 — had<br>22 — best<br>23 — are used<br>24 — children<br>25 — first<br>26 — me<br>27 — flew<br>28 — was",
   "steps": [
    "Текст с ответами:<div class=\"eng-text\"><p><span class=\"eng-num\">20</span> By today’s standards, my mobile phone is pretty basic. It’s a Nokia. It’s a small device that receives telephone calls and sends text messages. Other than that, my phone <b>does not do</b> much.</p><p><span class=\"eng-num\">21</span> Most of my friends wish they <b>had</b> smartphones because they are cool and trendy.</p><p><span class=\"eng-num\">22</span> They say the <b>best</b> thing about a smartphone is that you ‘can do everything with it!’</p><p><span class=\"eng-num\">23</span> That’s right, smartphones have many more functions than a simple phone, however, not all of them are needed. In everyday life, smartphones <b>are used</b> mainly for checking social networking sites, replying to emails, and playing games.</p><p><span class=\"eng-num\">24</span> Grown-ups as well as <b>children</b> like playing games.</p><p><span class=\"eng-num\">25</span> Anyway, I prefer my good old Nokia. It’s my <b>first</b> mobile phone.</p><p><span class=\"eng-num\">26</span> When I bought it, it didn’t cost <b>me</b> very much. And I am not afraid anyone will ever steal it.</p><p><span class=\"eng-num\">27</span> It’s also very reliable. Yesterday I dropped it. It <b>flew</b> down the staircase and hit the wall.</p><p><span class=\"eng-num\">28</span> I thought that <b>was</b> the end of it. But nothing of the kind – it still works properly!</p></div>"
   ],
