   "fipi": "2EB14E, EF6BB0, 7C1288, 74A37E, 0087E1, 186F62, 3B8B8B, 08A8DB, DBF8B2",
   "peek": "When you look at this lovely house in the Welsh countryside, you may think it’s a picture from a children’s book. ‘In fact it’s a real house designed by a real person. When … first son was born, Simon Dale’s wife, Jasmine, said:",
   "text": "<div class=\"eng-text\"><p class=\"eng-note\">Прочитайте приведённый ниже текст. Преобразуйте слова, напечатанные заглавными буквами в конце строк, обозначенных номерами 20 – 28, так, чтобы они грамматически соответствовали содержанию текста. Заполните пропуски полученными словами. Каждый пропуск соответствует отдельному заданию 20 – 28.</p><p><span class=\"eng-num\">20</span> When you look at this lovely house in the Welsh countryside, you may think it’s a picture from a children’s book. ‘In fact it’s a real house designed by a real person. When <span class=\"eng-gap\"></span> first son was born, Simon Dale’s wife, Jasmine, said: <span class=\"eng-word\">THEY</span></p><p><span class=\"eng-num\">21</span> “I wish we <span class=\"eng-gap\"></span> in the country. It would be so good for the baby”. <span class=\"eng-word\">LIVE</span></p><p><span class=\"eng-num\">22</span> However, they <span class=\"eng-gap\"></span> enough money to buy or rent a house in the country so they decided to take matters into their own hands. <span class=\"eng-word\">NOT HAVE</span></p><p><span class=\"eng-num\">23</span> The house <span class=\"eng-gap\"></span> by Simon himself, with a bit of help from his friends. The result is impressive. <span class=\"eng-word\">BUILD</span></p><p><span class=\"eng-num\">24</span> The home is made of natural materials, such as wood, stone and mud. It uses solar panels for energy, and its water <span class=\"eng-gap\"></span> from a nearby spring. <span class=\"eng-word\">COME</span></p><p><span class=\"eng-num\">25</span> It took Simon four months to complete his fairytale home. He managed to create a modern wooden eco-home – one of the <span class=\"eng-gap\"></span> houses you can imagine. <span class=\"eng-word\">WONDERFUL</span></p><p><span class=\"eng-num\">26</span> Simon Dale said, “I <span class=\"eng-gap\"></span> working on a new house of the same eco-style. <span class=\"eng-word\">START</span></p><p><span class=\"eng-num\">27</span> My <span class=\"eng-gap\"></span> house will be smarter than the first one. <span class=\"eng-word\">TWO</span></p><p><span class=\"eng-num\">28</span> My son <span class=\"eng-gap\"></span> five now and I hope to celebrate his tenth birthday in a new house.” <span class=\"eng-word\">BE</span></p></div>",
