   "answerTex": "<br>20 — their<br>21 — lived<br>22 — did not have<br>23 — was built<br>24 — comes<br>25 — most wonderful<br>26 — have started<br>27 — second<br>28 — is",
   "steps": [
    "Текст с ответами:<div class=\"eng-text\"><p><span class=\"eng-num\">20</span> When you look at this lovely house in the Welsh countryside, you may think it’s a picture from a children’s book. ‘In fact it’s a real house designed by a real person. When <b>their</b> first son was born, Simon Dale’s wife, Jasmine, said:</p><p><span class=\"eng-num\">21</span> “I wish we <b>lived</b> in the country. It would be so good for the baby”.</p><p><span class=\"eng-num\">22</span> However, they <b>did not have</b> enough money to buy or rent a house in the country so they decided to take matters into their own hands.</p><p><span class=\"eng-num\">23</span> The house <b>was built</b> by Simon himself, with a bit of help from his friends. The result is impressive.</p><p><span class=\"eng-num\">24</span> The home is made of natural materials, such as wood, stone and mud. It uses solar panels for energy, and its water <b>comes</b> from a nearby spring.</p><p><span class=\"eng-num\">25</span> It took Simon four months to complete his fairytale home. He managed to create a modern wooden eco-home – one of the <b>most wonderful</b> houses you can imagine.</p><p><span class=\"eng-num\">26</span> Simon Dale said, “I <b>have started</b> working on a new house of the same eco-style.</p><p><span class=\"eng-num\">27</span> My <b>second</b> house will be smarter than the first one.</p><p><span class=\"eng-num\">28</span> My son <b>is</b> five now and I hope to celebrate his tenth birthday in a new house.”</p></div>"
   ],
