   "text": "<div class=\"eng-text\"><p class=\"eng-note\">Прочитайте приведённый ниже текст. Преобразуйте слова, напечатанные заглавными буквами в конце строк, обозначенных номерами 20 – 28, так, чтобы они грамматически соответствовали содержанию текста. Заполните пропуски полученными словами. Каждый пропуск соответствует отдельному заданию 20 – 28.</p><p><span class=\"eng-num\">20</span> Harry’s class was going on an excursion to the firehouse. Harry <span class=\"eng-gap\"></span> proud because his Uncle Jim, a fireman, was going to show the children around the place. <span class=\"eng-word\">FEEL</span></p><p><span class=\"eng-num\">21</span> Naturally, the <span class=\"eng-gap\"></span> thing Harry’s classmates wanted to see was the huge fire truck. <span class=\"eng-word\">ONE</span></p><p><span class=\"eng-num\">22</span> There <span class=\"eng-gap\"></span> eight vehicles at the firehouse at that moment. Uncle Jim explained how the trucks got water and even let the kids get inside the truck. <span class=\"eng-word\">BE</span></p><p><span class=\"eng-num\">23</span> “Have you ever fought a fire yourself?” a red-haired boy asked. “Yes, many times, unfortunately,” Uncle Jim answered. “I wish people <span class=\"eng-gap\"></span> more responsibly when they used electrical devices at home or had picnics outdoors. <span class=\"eng-word\">BEHAVE</span></p><p><span class=\"eng-num\">24</span> But they often <span class=\"eng-gap\"></span> anything can happen to them. <span class=\"eng-word\">NOT THINK</span></p><p><span class=\"eng-num\">25</span> Please remember that you <span class=\"eng-gap\"></span> make fires in the woods. <span class=\"eng-word\">NOT MUST</span></p><p><span class=\"eng-num\">26</span> There is dry grass and dry <span class=\"eng-gap\"></span> on the ground. They start to burn very easily. <span class=\"eng-word\">LEAF</span></p><p><span class=\"eng-num\">27</span> And there is nothing <span class=\"eng-gap\"></span> than forest fires!” <span class=\"eng-word\">DANGEROUS</span></p><p><span class=\"eng-num\">28</span> The children promised not to make any fires in the woods and Uncle Jim went on with the tour. He <span class=\"eng-gap\"></span> them the fire alarm equipment, when a siren started wailing... <span class=\"eng-word\">SHOW</span></p></div>",
