   "answerTex": "<br>20 — felt<br>21 — first<br>22 — were<br>23 — behaved<br>24 — do not think<br>25 — must not<br>26 — leaves<br>27 — more dangerous<br>28 — was showing",
   "steps": [
    "Текст с ответами:<div class=\"eng-text\"><p><span class=\"eng-num\">20</span> Harry’s class was going on an excursion to the firehouse. Harry <b>felt</b> proud because his Uncle Jim, a fireman, was going to show the children around the place.</p><p><span class=\"eng-num\">21</span> Naturally, the <b>first</b> thing Harry’s classmates wanted to see was the huge fire truck.</p><p><span class=\"eng-num\">22</span> There <b>were</b> eight vehicles at the firehouse at that moment. Uncle Jim explained how the trucks got water and even let the kids get inside the truck.</p><p><span class=\"eng-num\">23</span> “Have you ever fought a fire yourself?” a red-haired boy asked. “Yes, many times, unfortunately,” Uncle Jim answered. “I wish people <b>behaved</b> more responsibly when they used electrical devices at home or had picnics outdoors.</p><p><span class=\"eng-num\">24</span> But they often <b>do not think</b> anything can happen to them.</p><p><span class=\"eng-num\">25</span> Please remember that you <b>must not</b> make fires in the woods.</p><p><span class=\"eng-num\">26</span> There is dry grass and dry <b>leaves</b> on the ground. They start to burn very easily.</p><p><span class=\"eng-num\">27</span> And there is nothing <b>more dangerous</b> than forest fires!”</p><p><span class=\"eng-num\">28</span> The children promised not to make any fires in the woods and Uncle Jim went on with the tour. He <b>was showing</b> them the fire alarm equipment, when a siren started wailing...</p></div>"
   ],
