   "text": "<div class=\"eng-text\"><p class=\"eng-note\">Прочитайте приведённый ниже текст. Преобразуйте слова, напечатанные заглавными буквами в конце строк, обозначенных номерами 20 – 28, так, чтобы они грамматически соответствовали содержанию текста. Заполните пропуски полученными словами. Каждый пропуск соответствует отдельному заданию 20 – 28.</p><p><span class=\"eng-num\">20</span> The camel was very thirsty. His last drink had been weeks ago. His feet sank in the hot sand and he <span class=\"eng-gap\"></span> hardly move. <span class=\"eng-word\">CAN</span></p><p><span class=\"eng-num\">21</span> “When will I reach water?” he thought. “And I <span class=\"eng-gap\"></span> for ages.” <span class=\"eng-word\">NOT EAT</span></p><p><span class=\"eng-num\">22</span> It was obvious that if the camel didn’t find any water and food soon, he<span class=\"eng-gap\"></span>. <span class=\"eng-word\">DIE</span></p><p><span class=\"eng-num\">23</span> He made a few steps toward another dune. It was <span class=\"eng-gap\"></span> to walk along the top of a hill, than along the bottom. <span class=\"eng-word\">EASY</span></p><p><span class=\"eng-num\">24</span> At last he <span class=\"eng-gap\"></span> something green in the distance. Was it a mirage or an oasis? <span class=\"eng-word\">SEE</span></p><p><span class=\"eng-num\">25</span> He hoped for the best and the hope helped <span class=\"eng-gap\"></span> move faster. <span class=\"eng-word\">HE</span></p><p><span class=\"eng-num\">26</span> Soon, that distant green colour turned into real trees and grass. There <span class=\"eng-gap\"></span> a small stream of water and some palm trees that gave shade. <span class=\"eng-word\">BE</span></p><p><span class=\"eng-num\">27</span> Their wide <span class=\"eng-gap\"></span> could protect the camel from the sun’s rays. <span class=\"eng-word\">LEAF</span></p><p><span class=\"eng-num\">28</span> Though the sun <span class=\"eng-gap\"></span>, it didn’t burn anymore. Unfortunately, it was impossible to stay there forever. A short rest and the camel had to move on towards his destination. <span class=\"eng-word\">SHINE</span></p></div>",
