   "text": "<div class=\"eng-text\"><p class=\"eng-note\">Прочитайте приведённый ниже текст. Преобразуйте слова, напечатанные заглавными буквами в конце строк, обозначенных номерами 20 – 28, так, чтобы они грамматически соответствовали содержанию текста. Заполните пропуски полученными словами. Каждый пропуск соответствует отдельному заданию 20 – 28.</p><p><span class=\"eng-num\">20</span> After school, I decided to go to university. I <span class=\"eng-gap\"></span> St Andrews University in Scotland. <span class=\"eng-word\">CHOOSE</span></p><p><span class=\"eng-num\">21</span> At that time I <span class=\"eng-gap\"></span> much about the University but when I arrived there, I liked it at once. <span class=\"eng-word\">NOT KNOW</span></p><p><span class=\"eng-num\">22</span> Now I'm in my last year and I wish I <span class=\"eng-gap\"></span> stay here forever! <span class=\"eng-word\">CAN</span></p><p><span class=\"eng-num\">23</span> St Andrews University is a truly special place. It <span class=\"eng-gap\"></span> 600 years ago and it is one of the oldest universities in the English-speaking world. <span class=\"eng-word\">BUILD</span></p><p><span class=\"eng-num\">24</span> It has many traditions – for example, the ‘May Dip’. It is held on the <span class=\"eng-gap\"></span> of May every year. <span class=\"eng-word\">ONE</span></p><p><span class=\"eng-num\">25</span> All the students run into the North Sea at sunrise to celebrate the coming of spring and for good luck! One of my classmates said that the tradition <span class=\"eng-gap\"></span> him to pass his exams last summer. <span class=\"eng-word\">HELP</span></p><p><span class=\"eng-num\">26</span> For me the ‘May Dip’ was the <span class=\"eng-gap\"></span> experience of my life! <span class=\"eng-word\">COLD</span></p><p><span class=\"eng-num\">27</span> Because the weather is famously cold, St Andrews students designed <span class=\"eng-gap\"></span> own uniform which consists of a warm jacket, jeans and boat shoes. <span class=\"eng-word\">THEY</span></p><p><span class=\"eng-num\">28</span> The uniform <span class=\"eng-gap\"></span> us all look the same, but it is the only way to keep warm! <span class=\"eng-word\">MAKE</span></p></div>",
