   "steps": [
    "Текст с ответами:<div class=\"eng-text\"><p><span class=\"eng-num\">20</span> Jenny loved climbing. It was a strange hobby for a girl and her family wanted her to stop it, but Jenny <b>did not listen</b> to anybody.</p><p><span class=\"eng-num\">21</span> “There are still several trees in the garden I haven’t climbed yet,” Jenny said. One day, she<b>was climbing</b> the apple tree in the yard, when she suddenly slipped and fell down.</p><p><span class=\"eng-num\">22</span> Jenny <b>felt</b> a terrible pain and started to cry. Her mum came outside and saw that her hand was swollen and looked dark.</p><p><span class=\"eng-num\">23</span> “I wish you <b>had</b> some other hobby!” she said.</p><p><span class=\"eng-num\">24</span> “Jenny, please, promise <b>me</b> that you’ll never do this silly climbing again!” Jenny nodded.</p><p><span class=\"eng-num\">25</span> Her mother took Jenny to the doctor. It turned out that two of the bones <b>were broken</b>.</p><p><span class=\"eng-num\">26</span> For the<b>first</b> time Jenny had a cast on her arm, from her fingers down to her elbow.</p><p><span class=\"eng-num\">27</span> For several weeks, Jenny had to have the cast on. It was a huge relief to get it off, finally. At last she could get back to her favourite <b>activities</b> which were running, swimming, and climbing.</p><p><span class=\"eng-num\">28</span> But now climbing was out – Jenny was determined to stick to her promise. “If I break my promise, mum <b>will get</b> upset. And I don’t want her to feel like this.”</p></div>"
   ],
