   "text": "<div class=\"eng-text\"><p class=\"eng-note\">Прочитайте приведённый ниже текст. Преобразуйте слова, напечатанные заглавными буквами в конце строк, обозначенных номерами 20 – 28, так, чтобы они грамматически соответствовали содержанию текста. Заполните пропуски полученными словами. Каждый пропуск соответствует отдельному заданию 20 – 28.</p><p><span class=\"eng-num\">20</span> Stonehenge is an ancient monument in south-west England. For me, it’s the <span class=\"eng-gap\"></span> place I’ve ever visited. <span class=\"eng-word\">INTERESTING</span></p><p><span class=\"eng-num\">21</span> I clearly remember my <span class=\"eng-gap\"></span> visit to Stonehenge with my aunt and uncle. <span class=\"eng-word\">ONE</span></p><p><span class=\"eng-num\">22</span> They lived nearby and I often <span class=\"eng-gap\"></span> to stay with them for my summer holidays. <span class=\"eng-word\">GO</span></p><p><span class=\"eng-num\">23</span> On the day of <span class=\"eng-gap\"></span> trip the weather was fine. <span class=\"eng-word\">WE</span></p><p><span class=\"eng-num\">24</span> There <span class=\"eng-gap\"></span> a cool wind blowing, the sun was bright in the sky and Stonehenge looked calm and magical. In those days it was possible to walk among the stones and even touch them. <span class=\"eng-word\">BE</span></p><p><span class=\"eng-num\">25</span> It's very different now. Stonehenge <span class=\"eng-gap\"></span> more crowded than it was. <span class=\"eng-word\">BECOME</span></p><p><span class=\"eng-num\">26</span> As a result, now people <span class=\"eng-gap\"></span> to walk around the monument but they can’t come up very close to it. <span class=\"eng-word\">ALLOW</span></p><p><span class=\"eng-num\">27</span> Today I wish I <span class=\"eng-gap\"></span> an opportunity to get inside the circle again but unfortunately it is not possible any more. <span class=\"eng-word\">HAVE</span></p><p><span class=\"eng-num\">28</span> The Stonehenge mystery is still unexplained but I believe scientists <span class=\"eng-gap\"></span> it in the near future. <span class=\"eng-word\">SOLVE</span></p></div>",
