   "text": "<div class=\"eng-text\"><p class=\"eng-note\">Прочитайте приведённый ниже текст. Преобразуйте слова, напечатанные заглавными буквами в конце строк, обозначенных номерами 20 – 28, так, чтобы они грамматически соответствовали содержанию текста. Заполните пропуски полученными словами. Каждый пропуск соответствует отдельному заданию 20 – 28.</p><p><span class=\"eng-num\">20</span> I remember my uncle Thomas very well. My mum says I can’t because I was a little girl, only three at the time. But my memories of him are still very vivid. Uncle Thomas was a sailor. When he returned from his last trip, he brought several large <span class=\"eng-gap\"></span> with him. <span class=\"eng-word\">BOX</span></p><p><span class=\"eng-num\">21</span> Inside there <span class=\"eng-gap\"></span> bits of wood, metal, and painted cloth. <span class=\"eng-word\">BE</span></p><p><span class=\"eng-num\">22</span> “What is it for?” I asked my uncle. He <span class=\"eng-gap\"></span> me a broad smile and said: “Have your breakfast first and then come to the backyard. <span class=\"eng-word\">GIVE</span></p><p><span class=\"eng-num\">23</span> You <span class=\"eng-gap\"></span> everything with your own eyes.” <span class=\"eng-word\">SEE</span></p><p><span class=\"eng-num\">24</span> When I came to the backyard, Uncle Thomas <span class=\"eng-gap\"></span> an instruction manual. <span class=\"eng-word\">READ</span></p><p><span class=\"eng-num\">25</span> It took all his attention because the manual <span class=\"eng-gap\"></span> in Spanish, a language my uncle didn’t know very well. <span class=\"eng-word\">WRITE</span></p><p><span class=\"eng-num\">26</span> All in all, it took <span class=\"eng-gap\"></span> a couple of weeks to assemble the object from the parts. <span class=\"eng-word\">HE</span></p><p><span class=\"eng-num\">27</span> To all my questions he said that it was a machine that <span class=\"eng-gap\"></span> fly like a bird. I was probably the only one in the family who took his words seriously. <span class=\"eng-word\">CAN</span></p><p><span class=\"eng-num\">28</span> They could never believe that soon we were going to see one of the <span class=\"eng-gap\"></span> airplane flights in the country. <span class=\"eng-word\">ONE</span></p></div>",
