    "Текст с ответами:<div class=\"eng-text\"><p><span class=\"eng-num\">20</span> Michael could not imagine his life without computers. His parents <b>bought</b> him his first computer at the age of six.</p><p><span class=\"eng-num\">21</span> It took <b>him</b> several days to learn how to use it.</p><p><span class=\"eng-num\">22</span> His mum said that younger people were much <b>faster</b> than adults at learning computer skills.</p><p><span class=\"eng-num\">23</span> That was probably true – most <b>children</b> in Michael’s class were very competent computer users.</p><p><span class=\"eng-num\">24</span> Michael was really surprised to find out that the first personal computer <b>was invented</b> in the 70s of the last century.</p><p><span class=\"eng-num\">25</span> “And how did you chat or send your e-mails without computers?” he asked his mother. She smiled: “We <b>did not send</b> each other e-mails. And there were no networks.”</p><p><span class=\"eng-num\">26</span> She also said that it <b>was</b> fun to communicate face-to-face, to play out-of-doors and to visit friends’ homes in those times.</p><p><span class=\"eng-num\">27</span> “But if there <b>were</b> no computers, I wouldn’t be able to communicate with my friends who live far away from me,” Michael replied.</p><p><span class=\"eng-num\">28</span> “True. Technological progress is a great thing,” his mother said. “And I think people <b>will create</b> even more amazing communication devices in the near future.”</p></div>"
